INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000067'::uuid, 'In the client-server model, which party initiates communication?', '{"A": "The load balancer", "B": "The client", "C": "The database", "D": "The server"}'::jsonb, 'B', 'In standard request-response architecture, the client sends a request and the server listens and responds.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000067'::uuid, 'What are the two main phases of a single HTTP request-response cycle?', '{"A": "DNS lookup only", "B": "Server pings client; client replies", "C": "Compile and deploy", "D": "Client sends request (method, path, headers, optional body); server processes and returns response (status, headers, optional body)"}'::jsonb, 'D', 'Every HTTP interaction pairs a client request with a server response.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000067'::uuid, 'Give an example of a client and a server in the Upskill web platform.', '{"A": "PostgreSQL calling React", "B": "React frontend in the browser (client) communicating with Spring Boot gateway (server)", "C": "CSS calling HTML", "D": "Git calling Maven"}'::jsonb, 'B', 'The browser-hosted React SPA acts as the client calling the Spring Boot backend server.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000068'::uuid, 'What does it mean for a server to be ''stateless''?', '{"A": "The client cannot send headers", "B": "The server has no database", "C": "The server never returns data", "D": "The server does not store client session state in memory between requests; each request carries all context needed"}'::jsonb, 'D', 'Statelessness means any server instance can handle any request independently.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000068'::uuid, 'Why is statelessness helpful when scaling backend servers horizontally?', '{"A": "It removes the need for a database", "B": "It makes JSON smaller", "C": "Any server instance can handle any request without needing sticky sessions or shared in-memory state", "D": "It disables HTTPS"}'::jsonb, 'C', 'Stateless servers can be added, removed, or load-balanced freely.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000069'::uuid, 'What is the primary role of a load balancer?', '{"A": "To distribute incoming client traffic across multiple backend server instances", "B": "To compile Java code", "C": "To replace SQL databases", "D": "To store user passwords"}'::jsonb, 'A', 'Load balancers prevent single-server overload and improve availability.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000069'::uuid, 'What is a reverse proxy (e.g., Nginx, Envoy, Cloudflare)?', '{"A": "A proxy running inside the user''s browser", "B": "A DNS server", "C": "A database trigger", "D": "An intermediary sitting in front of backend servers that receives client requests and forwards them to upstream servers"}'::jsonb, 'D', 'A reverse proxy protects, routes, terminates TLS, and load-balances traffic on the server side.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000069'::uuid, 'What does ''horizontal scaling'' (scaling out) mean?', '{"A": "Adding more server instances behind a load balancer", "B": "Upgrading a single server''s CPU/RAM", "C": "Increasing font size", "D": "Making the database table wider"}'::jsonb, 'A', 'Horizontal scaling adds more machines/containers, whereas vertical scaling upgrades one machine.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000067'::uuid, 'How does a forward proxy differ from a reverse proxy?', '{"A": "They are identical", "B": "Reverse proxies run on the client''s laptop", "C": "A forward proxy acts on behalf of clients (outbound); a reverse proxy acts on behalf of servers (inbound)", "D": "Forward proxies only handle SQL"}'::jsonb, 'C', 'Corporate outbound proxies are forward proxies; Nginx/ALB in front of Spring Boot is a reverse proxy.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000068'::uuid, 'Compare storing auth state in server-side HTTP sessions vs stateless JWT Bearer tokens.', '{"A": "JWTs are stored in server RAM", "B": "Sessions store state in server/Redis memory referenced by a session cookie; JWTs encode signed claims sent on each request", "C": "Sessions require no cookies or IDs", "D": "JWTs cannot expire"}'::jsonb, 'B', 'Server sessions allow instant revocation in store; JWTs avoid per-request session-store lookups.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000068'::uuid, 'Why is ''sticky sessions'' (session affinity) a potential bottleneck in load-balanced architectures?', '{"A": "Browsers reject sticky sessions", "B": "If one server crashes, pinned users lose their in-memory session, and traffic distribution can become uneven", "C": "Sticky sessions disable HTTPS", "D": "Sticky sessions double database size"}'::jsonb, 'B', 'Externalizing state (Redis/DB) or using stateless tokens avoids single-instance affinity.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000069'::uuid, 'How does a Round-Robin load-balancing algorithm differ from Least-Connections?', '{"A": "Least-Connections only works for UDP", "B": "Round-Robin cycles sequentially across servers; Least-Connections sends new requests to the server with fewest active connections", "C": "They are identical", "D": "Round-Robin uses CPU temperature"}'::jsonb, 'B', 'Least-Connections adapts better when request processing times vary widely.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000069'::uuid, 'What is a health check endpoint (e.g., ''/actuator/health'') used for by a load balancer?', '{"A": "To clear browser cache", "B": "To detect unhealthy/crashed backend instances and stop routing traffic to them", "C": "To check user passwords", "D": "To run Flyway migrations"}'::jsonb, 'B', 'Periodic health probes enable automatic failover away from failing instances.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000067'::uuid, 'When a client needs real-time server-pushed updates without polling, which protocols break out of strict request-response?', '{"A": "DNS", "B": "FTP", "C": "SMTP", "D": "WebSockets or Server-Sent Events (SSE)"}'::jsonb, 'D', 'WebSockets provide full-duplex messaging and SSE provides server-to-client event streaming.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000069'::uuid, 'What is TLS termination at a reverse proxy / load balancer?', '{"A": "Disabling encryption permanently", "B": "Blocking port 443", "C": "Decrypting HTTPS at the edge load balancer and forwarding plain HTTP (or re-encrypted traffic) inside a private VPC to backends", "D": "Dropping expired users"}'::jsonb, 'C', 'Offloading TLS handshakes to the edge simplifies certificate management and saves backend CPU.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000067'::uuid, 'Why should a backend server enforce request timeouts (connect, read, write) when calling downstream services?', '{"A": "Timeouts speed up CPU clock", "B": "HTTP requires 1ms timeout", "C": "Without timeouts, a slow downstream dependency can hang threads indefinitely and cause cascading failure", "D": "Timeouts replace indexes"}'::jsonb, 'C', 'Bounded timeouts prevent thread-pool exhaustion during partial outages.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000068'::uuid, 'Why does ''stateless server'' NOT mean ''stateless application''?', '{"A": "Application state still lives persistently in databases/caches (like PostgreSQL/Redis), just not in ephemeral web-server RAM", "B": "Stateless apps cannot have users", "C": "PostgreSQL is stateless", "D": "Browsers store the entire database"}'::jsonb, 'A', 'Persistent state is pushed to the data tier so web/API nodes remain disposable.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000069'::uuid, 'What is rate limiting at an API gateway / reverse proxy?', '{"A": "Limiting database columns", "B": "Compressing JSON", "C": "Slowing down CSS", "D": "Throttling excessive requests per client/IP/token (returning 429 Too Many Requests) to protect backend capacity"}'::jsonb, 'D', 'Rate limiting protects against abuse, scraping, and accidental client retry storms.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000069'::uuid, 'How does Layer 4 (Transport) load balancing differ from Layer 7 (Application) load balancing?', '{"A": "L4 routes on IP/TCP port without inspecting HTTP; L7 terminates HTTP and can route by URL path, headers, or cookies", "B": "L4 inspects JSON bodies", "C": "L4 supports URL path routing", "D": "L7 is only for UDP"}'::jsonb, 'A', 'L4 offers raw packet speed; L7 enables smart HTTP routing, WAF rules, and header manipulation.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000068'::uuid, 'When a reverse proxy forwards a request to Spring Boot, why might Spring Boot see the proxy''s IP instead of the client''s real IP, and how is it fixed?', '{"A": "Disable NAT", "B": "The TCP connection comes from the proxy; configure ''X-Forwarded-For'' / ''X-Forwarded-Proto'' headers and trusted proxy settings in Spring", "C": "Read MAC address", "D": "Use UDP instead"}'::jsonb, 'B', 'Only trust X-Forwarded-* headers from known proxy IPs to prevent client IP spoofing.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000069'::uuid, 'What is Consistent Hashing in distributed caching/load balancing, and why is it used?', '{"A": "It enforces ACID", "B": "It hashes passwords with BCrypt", "C": "It runs Round-Robin twice", "D": "It maps servers and keys onto a hash ring so adding/removing a server remaps only ~1/N keys instead of invalidating almost all caches"}'::jsonb, 'D', 'Consistent hashing minimizes cache misses during cluster scaling events.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000067'::uuid, 'What is the Circuit Breaker resilience pattern in microservices/backend gateways?', '{"A": "Dropping the database", "B": "Automatically failing fast (OPEN state) when a downstream service repeatedly errors, then probing recovery (HALF-OPEN) before closing", "C": "Shutting down the JVM", "D": "Retrying infinitely in a tight loop"}'::jsonb, 'B', 'Circuit breakers prevent cascading thread exhaustion and give struggling services time to recover.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000069'::uuid, 'What is ''graceful shutdown'' for a backend server behind a load balancer?', '{"A": "kill -9 immediately", "B": "Deleting logs", "C": "Deregistering from LB / failing readiness probe, stopping new requests, and finishing in-flight requests before exiting", "D": "Restarting PostgreSQL first"}'::jsonb, 'C', 'Graceful shutdown (supported by Spring Boot ''server.shutdown=graceful'') prevents 502 errors during rolling deploys.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'client-server-architecture'), '70000000-0000-0000-0000-000000000068'::uuid, 'Why must ''retries'' on failed requests from client/gateway be paired with exponential backoff + jitter?', '{"A": "HTTP forbids immediate retries", "B": "To make requests slower intentionally", "C": "Without backoff and jitter, synchronized retries from many clients create a ''thundering herd'' that keeps a recovering server down", "D": "Jitter encrypts payloads"}'::jsonb, 'C', 'Randomized jitter spreads retry load smoothly over time.', 'ADVANCED', TRUE);

