INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000071'::uuid, 'What does HTTPS add on top of plain HTTP?', '{"A": "Faster DNS", "B": "Larger JSON limits", "C": "TLS (Transport Layer Security) encryption, integrity, and server authentication", "D": "SQL injection protection"}'::jsonb, 'C', 'HTTPS runs HTTP inside an encrypted, authenticated TLS tunnel.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
