INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000072'::uuid, 'What happens in a browser if a server''s TLS certificate is expired or signed by an untrusted CA?', '{"A": "It refreshes the certificate automatically", "B": "It silently falls back to HTTP", "C": "It sends the password anyway", "D": "The browser displays a security warning and blocks/halts the connection by default"}'::jsonb, 'D', 'Certificate validation failure stops man-in-the-middle attacks.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000072'::uuid, 'What does the HSTS (Strict-Transport-Security) response header instruct browsers to do?', '{"A": "Disable cookies", "B": "Cache HTML forever", "C": "Always connect to that domain over HTTPS only, refusing plain HTTP for a specified max-age", "D": "Allow CORS from any origin"}'::jsonb, 'C', 'HSTS prevents SSL-stripping downgrade attacks.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000070'::uuid, 'How does ''Cache-Control: no-store'' differ from ''Cache-Control: no-cache''?', '{"A": "no-cache forbids storing anything", "B": "no-store forbids caching anywhere (sensitive data); no-cache allows storing a copy but requires revalidating with the server before reuse", "C": "They are identical", "D": "no-store only affects images"}'::jsonb, 'B', 'Use no-store for sensitive responses; no-cache for conditional ETag/Last-Modified revalidation.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000070'::uuid, 'Why is the ''Host'' header mandatory in HTTP/1.1 requests?', '{"A": "To pass the client''s hostname", "B": "To encrypt the URL", "C": "To enable virtual hosting—allowing one IP/port to serve multiple domain names", "D": "To replace DNS"}'::jsonb, 'C', 'A single Nginx/server IP often hosts dozens of domains distinguished by the Host header.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000070'::uuid, 'What is the ''ETag'' header used for?', '{"A": "Conditional requests / caching (If-None-Match -> 304 Not Modified) and optimistic concurrency (If-Match)", "B": "CORS preflight", "C": "TLS cipher selection", "D": "Authentication"}'::jsonb, 'A', 'ETags identify resource versions to avoid re-downloading unchanged responses or overwriting stale edits.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000071'::uuid, 'Why does TLS use asymmetric (public/private key) cryptography during the handshake and symmetric encryption for bulk data?', '{"A": "TLS does not use symmetric keys", "B": "Symmetric crypto cannot encrypt HTTP", "C": "Asymmetric crypto is faster", "D": "Asymmetric crypto authenticates identity and establishes a shared session key; symmetric crypto (AES-GCM/ChaCha20) is orders of magnitude faster for bulk traffic"}'::jsonb, 'D', 'Hybrid cryptography combines secure key exchange with high-speed symmetric encryption.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000071'::uuid, 'What is Perfect Forward Secrecy (PFS) in TLS (e.g., ECDHE key exchange)?', '{"A": "Each session generates ephemeral keys so compromising the server''s long-term private key later cannot decrypt past recorded traffic", "B": "Certificates never expire", "C": "TLS skips the handshake", "D": "Passwords never expire"}'::jsonb, 'A', 'TLS 1.3 mandates ephemeral Diffie-Hellman (ECDHE) for forward secrecy.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000071'::uuid, 'How many round-trips does a standard TLS 1.3 handshake take compared to TLS 1.2?', '{"A": "TLS 1.3 has no handshake", "B": "TLS 1.3 takes 1-RTT (and supports 0-RTT resumption), vs 2-RTT in TLS 1.2", "C": "Both take 3 round-trips", "D": "TLS 1.3 takes 5 round-trips"}'::jsonb, 'B', 'TLS 1.3 removes obsolete cipher negotiation and completes key exchange in 1 round-trip.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000072'::uuid, 'What is a certificate chain (Leaf -> Intermediate CA -> Root CA)?', '{"A": "Root CAs sign Intermediate CAs (kept offline for safety), which sign server Leaf certificates; clients verify signatures up to a trusted Root", "B": "Three copies of the same private key", "C": "A chain of load balancers", "D": "A list of expired domains"}'::jsonb, 'A', 'Missing intermediate certificates from the server''s TLS config is a common cause of mobile/API trust errors.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000072'::uuid, 'What does SAN (Subject Alternative Name) in a TLS certificate specify?', '{"A": "The port number", "B": "The server''s OS", "C": "The exact domain names / wildcard domains / IPs for which the certificate is valid", "D": "The cipher suite"}'::jsonb, 'C', 'Modern browsers validate hostnames strictly against SAN entries (ignoring the legacy CN field).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000070'::uuid, 'What security flags should be set on a cookie holding a session ID or refresh token?', '{"A": "HttpOnly, Secure, and SameSite=Lax/Strict", "B": "No flags needed", "C": "Max-Age=999999999 only", "D": "Public, Writable"}'::jsonb, 'A', 'HttpOnly blocks JS access (XSS mitigation), Secure requires HTTPS, and SameSite mitigates CSRF.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000072'::uuid, 'What is mutual TLS (mTLS)?', '{"A": "Using two CAs", "B": "Allowing expired certs", "C": "Encrypting traffic twice with HTTP", "D": "Both the server AND the client present and verify X.509 certificates during the TLS handshake"}'::jsonb, 'D', 'mTLS provides strong cryptographic service-to-service authentication.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000071'::uuid, 'What is SNI (Server Name Indication) in the TLS ClientHello, and why is it needed?', '{"A": "SNI replaces the Host header", "B": "SNI encrypts DNS", "C": "The client sends the target hostname unencrypted in ClientHello so a shared IP/load balancer knows which TLS certificate to present before HTTP begins", "D": "SNI is only in TLS 1.0"}'::jsonb, 'C', 'Without SNI, a server hosting multiple HTTPS domains on one IP wouldn''t know which cert to return during the TLS handshake.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000071'::uuid, 'What is ALPN (Application-Layer Protocol Negotiation) in TLS?', '{"A": "A CORS header", "B": "A way for client and server to agree on HTTP/2 (''h2'') vs HTTP/1.1 during the TLS handshake without an extra round-trip", "C": "A certificate revocation list", "D": "A password hashing scheme"}'::jsonb, 'B', 'ALPN negotiates h2 or http/1.1 inside the TLS handshake itself.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000072'::uuid, 'Compare CRL (Certificate Revocation List) vs OCSP Stapling for checking revoked certificates.', '{"A": "Browsers check neither", "B": "OCSP Stapling disables TLS", "C": "CRL is faster and real-time", "D": "CRL downloads huge lists periodically; OCSP Stapling has the server attach a fresh CA-signed OCSP status response during the TLS handshake, preserving client privacy and speed"}'::jsonb, 'D', 'OCSP stapling avoids live client-to-CA queries during TLS handshakes.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000070'::uuid, 'Why is HTTP/2 header compression (HPACK) safer than HTTP/1.1 TLS-level compression (which suffered from CRIME/BREACH)?', '{"A": "HTTP/2 sends headers in plain TCP", "B": "HPACK uses static/dynamic header tables and Huffman coding rather than LZ77 sliding-window compression across secret+attacker-controlled text", "C": "HTTP/2 disables encryption", "D": "HPACK compresses only numbers"}'::jsonb, 'B', 'CRIME exploited LZ77 compression length leaks on cookies; HPACK was specifically designed to avoid cross-context compression oracles.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000070'::uuid, 'Why does setting ''Access-Control-Allow-Origin: *'' together with ''Access-Control-Allow-Credentials: true'' fail in browsers?', '{"A": "Credentials require HTTP/1.0", "B": "CORS only applies to GET", "C": "The CORS spec forbids wildcard ''*'' with credentials to prevent any arbitrary malicious site from making credentialed requests", "D": "Browsers don''t support ''*''"}'::jsonb, 'C', 'With credentials, the server must echo a specific validated origin rather than ''*''.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-https'), '70000000-0000-0000-0000-000000000072'::uuid, 'Why can TLS 1.3 0-RTT early data be dangerous for non-idempotent POST endpoints?', '{"A": "0-RTT strips headers", "B": "0-RTT data lacks forward-secrecy replay protection and can be replayed by a network attacker", "C": "0-RTT only works on port 80", "D": "0-RTT is unencrypted"}'::jsonb, 'B', 'Only safe, idempotent requests (like GET) should be accepted over 0-RTT early data.', 'ADVANCED', TRUE);

-- Skill: rest-api-architecture
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000073'::uuid, 'In REST API design, should resource URI paths primarily use nouns or verbs?', '{"A": "Plural nouns representing resources (e.g., /api/skills, /api/attempts), while HTTP methods express the action", "B": "Random hashes", "C": "Database SQL table commands", "D": "Verbs like /getUsers or /createAttempt"}'::jsonb, 'A', 'REST models resources as nouns (/skills/{id}) and actions via HTTP verbs (GET, POST, PUT, DELETE).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000073'::uuid, 'Which URI better represents fetching a specific milestone attempt?', '{"A": "/api/milestone_attempt_select/123", "B": "/api/doFetch/123", "C": "/api/getMilestoneAttemptById?id=123", "D": "/api/milestone/attempts/123"}'::jsonb, 'D', 'Hierarchical noun paths cleanly identify resource collections and specific instances.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000073'::uuid, 'Which data exchange format is the standard default for modern REST APIs?', '{"A": "Binary Java Serialization", "B": "INI", "C": "JSON", "D": "CSV"}'::jsonb, 'C', 'JSON is lightweight, human-readable, and natively supported in browsers and backend frameworks.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000074'::uuid, 'What does the REST ''Stateless'' constraint require?', '{"A": "Each HTTP request from client to server must contain all information needed to understand and process it (no server session memory)", "B": "The API cannot save data to PostgreSQL", "C": "Only GET requests are allowed", "D": "Responses cannot return JSON"}'::jsonb, 'A', 'The server must not rely on stored conversational state from previous HTTP requests.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000074'::uuid, 'Which REST architectural constraint allows responses to be labeled as cacheable or non-cacheable?', '{"A": "Layered System", "B": "Uniform Interface", "C": "Code-on-Demand", "D": "Cacheable"}'::jsonb, 'D', 'Explicit cacheability metadata (Cache-Control, ETag) reduces redundant client-server traffic.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000075'::uuid, 'Why do REST APIs use versioning (e.g., ''/api/v1/skills'')?', '{"A": "To disable caching", "B": "To bypass authentication", "C": "To make URLs longer", "D": "To introduce breaking schema/contract changes without breaking existing clients"}'::jsonb, 'D', 'Versioning lets old clients stay on v1 while new clients adopt v2.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000075'::uuid, 'What is pagination in a REST collection endpoint like ''GET /api/questions?page=0&size=20''?', '{"A": "Printing HTML pages", "B": "Encrypting responses", "C": "Deleting old rows", "D": "Splitting a large result set into smaller chunks/pages to avoid huge payloads and memory spikes"}'::jsonb, 'D', 'Pagination bounds response latency, bandwidth, and database load.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000075'::uuid, 'What is HATEOAS in REST?', '{"A": "A SQL dialect", "B": "Hypermedia as the Engine of Application State — responses include links to related actions/resources", "C": "An authentication algorithm", "D": "A JSON minifier"}'::jsonb, 'B', 'HATEOAS lets clients discover next valid state transitions dynamically from links in the payload.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000073'::uuid, 'When should a query parameter be used instead of a path parameter in REST?', '{"A": "Path parameter to identify a specific resource (/skills/{id}); query parameter for filtering, sorting, or pagination (?difficulty=BEGINNER&page=0)", "B": "Always use path parameters for pagination", "C": "Always use query parameters for everything", "D": "They are interchangeable"}'::jsonb, 'A', 'Path segments identify resources; query strings filter/sort/paginate views of resources.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000073'::uuid, 'How should an action that doesn''t map cleanly to CRUD (like submitting an assessment) be designed in REST?', '{"A": "DELETE /attempts/{id}", "B": "HEAD /attempts/{id}", "C": "GET /attempts/{id}/submit", "D": "POST /attempts/{id}/submit (treating submission as a sub-resource/command on the attempt)"}'::jsonb, 'D', 'State-changing operations should use POST (never GET) on a clear sub-resource.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000074'::uuid, 'In REST, what is the ''Layered System'' constraint?', '{"A": "Database must have 3 tables", "B": "All code must be in one class", "C": "JSON must be nested 3 levels", "D": "Clients cannot tell whether they are connected directly to the origin server or through intermediaries (CDN, gateway, load balancer)"}'::jsonb, 'D', 'Intermediaries can be inserted transparently for caching, security, and scaling.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000074'::uuid, 'Why is storing the ''current question index'' ONLY in server RAM on a REST endpoint a violation of REST?', '{"A": "Server RAM cannot store integers", "B": "It violates HTTPS", "C": "It violates Statelessness and breaks if the next request hits a different backend instance", "D": "JSON cannot carry integers"}'::jsonb, 'C', 'Persist progress in PostgreSQL/Redis or pass state explicitly in the request.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000075'::uuid, 'Compare URI path versioning (''/api/v1/users'') vs Header/Media-type versioning (''Accept: application/vnd.app.v2+json'').', '{"A": "URI versioning breaks HTTPS", "B": "URI versioning is explicit, easy to test/cache/route; Header versioning keeps URIs pure but is harder to test in browsers", "C": "Header versioning is impossible in Spring Boot", "D": "They are identical"}'::jsonb, 'B', 'URI versioning is the most pragmatic and widely adopted style for public and internal REST APIs.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000075'::uuid, 'What information should a standardized REST error response body (e.g., RFC 9457 Problem Details) include?', '{"A": "HTML error page", "B": "Full SQL stack traces and DB passwords", "C": "HTTP status, machine-readable error code/type, human-readable message, timestamp, and path (never internal stack traces)", "D": "Empty body always"}'::jsonb, 'C', 'Consistent structured errors help clients handle failures safely without leaking internals.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000073'::uuid, 'What is the risk of returning JPA ''@Entity'' classes directly from REST controllers instead of DTOs?', '{"A": "Infinite JSON recursion on bidirectional relations, lazy-loading exceptions, and accidental exposure of sensitive fields like password_hash", "B": "JPA entities cannot be serialized", "C": "DTOs use more SQL", "D": "Controllers cannot return DTOs"}'::jsonb, 'A', 'Dedicated DTOs decouple the external API contract from internal database tables.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000075'::uuid, 'Which change is considered a NON-breaking (backward-compatible) REST API evolution?', '{"A": "Removing an endpoint", "B": "Changing a string field to an integer", "C": "Renaming a required JSON field", "D": "Adding a new optional field to a response JSON object"}'::jsonb, 'D', 'Additive optional fields allow existing clients to ignore unknown properties safely.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000074'::uuid, 'What does ''Uniform Interface'' in REST require?', '{"A": "All endpoints return the same JSON", "B": "Every field is a String", "C": "Only one endpoint per server", "D": "Consistent resource identification, manipulation via representations, self-descriptive messages, and hypermedia"}'::jsonb, 'D', 'Uniform Interface decouples client and server implementations so each can evolve independently.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000073'::uuid, 'In REST, how should nested relationships like questions belonging to an attempt be structured?', '{"A": "/api/select/questions", "B": "/api/attempt?q=1&q=2", "C": "/api/questions_by_attempt_get", "D": "/api/milestone/attempts/{attemptId}/questions"}'::jsonb, 'D', 'Sub-collection paths express ownership clearly (limit nesting depth to 2–3 levels).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000075'::uuid, 'Compare Offset pagination (''?page=50&size=20'') vs Cursor/Keyset pagination (''?cursor=eyJpZCI6MTAwfQ&limit=20'') in a live feed.', '{"A": "Cursor pagination cannot use indexes", "B": "Offset suffers from drifting/duplicate items when new rows are inserted and O(offset) DB scans; cursor pagination stays consistent and O(log n)", "C": "Offset is always faster", "D": "Cursor pagination only works in GraphQL"}'::jsonb, 'B', 'Cursor pagination avoids skipped/duplicated items on mutating datasets.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000075'::uuid, 'How can a REST API support optimistic concurrency control to prevent lost updates when two clients edit the same resource?', '{"A": "Return an ETag (version) on GET and require ''If-Match: <etag>'' on PUT/PATCH, returning 412 Precondition Failed if stale", "B": "Lock the browser tab", "C": "Disable PATCH", "D": "Use GET to update"}'::jsonb, 'A', 'HTTP ETag + If-Match maps cleanly onto JPA @Version optimistic locking.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000073'::uuid, 'When designing a REST endpoint for long-running background jobs (e.g., report export), what status code and pattern should be used?', '{"A": "Return 504 immediately", "B": "Return 200 OK with empty body", "C": "Return 202 Accepted with a Location header pointing to a status resource (/jobs/{jobId})", "D": "Block the HTTP thread for 10 minutes"}'::jsonb, 'C', '202 Accepted + polling/webhook status resource prevents HTTP gateway timeouts.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000074'::uuid, 'What is the BFF (Backend for Frontend) pattern and why does it complement REST APIs?', '{"A": "Replacing PostgreSQL with localStorage", "B": "Putting SQL inside React", "C": "A dedicated API layer tailored to a specific UI client (web vs mobile) that aggregates/shapes backend calls to reduce over-fetching and round-trips", "D": "Bypassing authentication"}'::jsonb, 'C', 'A BFF adapts coarse domain services to exact screen needs without polluting core APIs.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000075'::uuid, 'How does the ''Sunset'' and ''Deprecation'' HTTP response headers help manage API lifecycle?', '{"A": "They notify API consumers programmatically of deprecated endpoints and their scheduled removal date", "B": "They rotate JWT keys", "C": "They shut down the server at night", "D": "They compress JSON"}'::jsonb, 'A', 'Standardized Deprecation/Sunset headers enable automated client monitoring before v1 removal.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'rest-api-architecture'), '70000000-0000-0000-0000-000000000073'::uuid, 'Why should PATCH requests use a well-defined format (such as JSON Merge Patch RFC 7396 or JSON Patch RFC 6902) or explicit null-vs-omitted handling?', '{"A": "To distinguish ''field omitted (leave unchanged)'' from ''field explicitly set to null (clear value)''", "B": "To force full replacement like PUT", "C": "Because JSON doesn''t allow nulls", "D": "PATCH cannot have a body"}'::jsonb, 'A', 'Distinguishing absent vs null prevents accidental data erasure during partial updates.', 'ADVANCED', TRUE);

-- Skill: http-methods-status-codes
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000076'::uuid, 'Which HTTP method is used to retrieve a resource without modifying server state?', '{"A": "DELETE", "B": "PUT", "C": "POST", "D": "GET"}'::jsonb, 'D', 'GET is safe and read-only.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000076'::uuid, 'How do PUT and PATCH differ semantically?', '{"A": "PATCH deletes the resource; PUT creates it", "B": "PUT replaces the entire target resource; PATCH applies a partial update", "C": "They are identical", "D": "PUT is read-only"}'::jsonb, 'B', 'PUT sends a complete representation; PATCH sends only the fields to modify.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000076'::uuid, 'Which HTTP method is standard for creating a new subordinate resource (e.g., starting a new milestone attempt)?', '{"A": "OPTIONS", "B": "GET", "C": "POST", "D": "HEAD"}'::jsonb, 'C', 'POST submits data to create a new resource or trigger a non-idempotent action.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000077'::uuid, 'What do HTTP status codes in the 2xx, 4xx, and 5xx ranges indicate?', '{"A": "2xx: Redirect; 4xx: Success; 5xx: Client error", "B": "2xx: Success; 4xx: Client error; 5xx: Server error", "C": "4xx: Server crash; 5xx: Invalid JSON", "D": "All indicate errors"}'::jsonb, 'B', '2xx = success, 3xx = redirection, 4xx = client fault, 5xx = server failure.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000077'::uuid, 'What is the difference between 401 Unauthorized and 403 Forbidden?', '{"A": "403 means invalid JSON", "B": "401 means server error; 403 means not found", "C": "401 means unauthenticated (missing/invalid credentials); 403 means authenticated but lacking permission for the resource", "D": "They are identical"}'::jsonb, 'C', '401 = ''who are you?''; 403 = ''I know who you are, and you''re not allowed''.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000077'::uuid, 'Which status code is ideal when a resource is successfully created via POST?', '{"A": "204 No Content", "B": "201 Created", "C": "400 Bad Request", "D": "200 OK"}'::jsonb, 'B', '201 Created (often paired with a Location header) specifically indicates a new resource was created.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000078'::uuid, 'What does ''idempotent'' mean for an HTTP method?', '{"A": "It never modifies data", "B": "It runs very fast", "C": "Making the exact same request once or multiple times produces the same final server state", "D": "It requires no body"}'::jsonb, 'C', 'Repeated identical idempotent calls leave the resource in the same state as a single call.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000078'::uuid, 'Which common HTTP methods are idempotent according to the HTTP specification?', '{"A": "POST and PATCH", "B": "Only POST", "C": "GET, HEAD, PUT, DELETE, OPTIONS", "D": "Only GET"}'::jsonb, 'C', 'GET, PUT, and DELETE are defined as idempotent; POST is NOT idempotent.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000076'::uuid, 'When is ''204 No Content'' the most appropriate success status code?', '{"A": "When validation fails", "B": "When an operation succeeds (such as DELETE or an update) and there is no response body to return", "C": "When returning a list of 10 users", "D": "When a record is not found"}'::jsonb, 'B', '204 explicitly signals success with an empty body.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000077'::uuid, 'When should an API return ''400 Bad Request'' vs ''404 Not Found'' vs ''409 Conflict''?', '{"A": "401 for missing resource", "B": "404 for everything", "C": "500 for validation errors", "D": "400: malformed syntax/validation error; 404: target resource ID doesn''t exist; 409: state conflict (e.g., duplicate email or attempt already completed)"}'::jsonb, 'D', 'Precise 4xx codes let clients distinguish validation mistakes from missing entities or state conflicts.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000077'::uuid, 'What does ''422 Unprocessable Content (Entity)'' indicate compared to ''400 Bad Request''?', '{"A": "Rate limit exceeded", "B": "Auth failed", "C": "Server crashed", "D": "The JSON syntax is valid, but semantic/business validation failed"}'::jsonb, 'D', '422 is widely used for domain/field validation errors on well-formed JSON.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000077'::uuid, 'What is the difference between ''500 Internal Server Error'', ''502 Bad Gateway'', ''503 Service Unavailable'', and ''504 Gateway Timeout''?', '{"A": "500: unhandled server bug; 502: invalid response from upstream; 503: overloaded/maintenance; 504: upstream timed out", "B": "502 means invalid JWT", "C": "503 means not found", "D": "All mean client bug"}'::jsonb, 'A', 'Gateway codes (502/504) pinpoint upstream failures in reverse-proxy architectures.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000078'::uuid, 'Why is ''GET'' considered both ''safe'' and ''idempotent'', while ''DELETE'' is ''idempotent'' but NOT ''safe''?', '{"A": "Safe means no server-side state mutation; GET doesn''t mutate state, whereas DELETE mutates state (deletes the row), yet repeating DELETE leaves the row deleted", "B": "DELETE never modifies state", "C": "They mean the same thing", "D": "GET mutates state"}'::jsonb, 'A', 'All safe methods are idempotent, but not all idempotent methods are safe.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000078'::uuid, 'Why is ''POST'' generally NOT idempotent?', '{"A": "POST is encrypted", "B": "POST returns 404 on retry", "C": "POST has no body", "D": "Calling POST /orders twice creates two separate orders"}'::jsonb, 'D', 'Repeating a non-idempotent POST can create duplicate records or double-charge payments.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000076'::uuid, 'What is the purpose of an ''OPTIONS'' HTTP request in web browsers?', '{"A": "CORS preflight check: browser asks the server which origins, methods, and headers are permitted before sending the actual request", "B": "To delete cookies", "C": "To download metadata", "D": "To reset TLS"}'::jsonb, 'A', 'Browsers send OPTIONS preflight requests for cross-origin requests with custom headers or methods like PUT/DELETE/JSON POST.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000076'::uuid, 'How does ''HEAD'' differ from ''GET''?', '{"A": "HEAD returns the exact same status and headers as GET, but WITHOUT the response body", "B": "HEAD returns only the body", "C": "HEAD modifies the resource", "D": "HEAD is an error method"}'::jsonb, 'A', 'HEAD efficiently checks resource existence, Content-Length, or ETag without transferring payload bytes.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000077'::uuid, 'Which status code indicates a client has exceeded the API rate limit?', '{"A": "503", "B": "413", "C": "403", "D": "429 Too Many Requests"}'::jsonb, 'D', '429 (often with a Retry-After header) signals rate-limit throttling.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000078'::uuid, 'Why should a ''POST /milestone/attempts/{id}/submit'' endpoint fail with 400/409 if the attempt is already COMPLETED?', '{"A": "To prevent double-submitting and incrementing user_skill_mastery.evidence_count multiple times for the same attempt", "B": "PostgreSQL crashes on second update", "C": "JSON becomes invalid", "D": "POST cannot return 200"}'::jsonb, 'A', 'MilestoneService explicitly checks if status == COMPLETED and throws 400 Bad Request to guard against duplicate submission.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000078'::uuid, 'How do payment/order APIs make a normally non-idempotent ''POST /payments'' safely retryable over unreliable networks?', '{"A": "Use PUT without an ID", "B": "Switch to GET", "C": "Require an ''Idempotency-Key'' header (UUID) stored atomically with the response in DB/Redis so retries return the original result without re-executing", "D": "Disable retries"}'::jsonb, 'C', 'Idempotency keys guarantee at-most-once execution despite network retries.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000078'::uuid, 'Can a ''PATCH'' request be non-idempotent? Give an example.', '{"A": "No, PATCH is always idempotent", "B": "PATCH cannot modify numbers", "C": "Yes: e.g., PATCH with ''{ \"op\": \"increment\", \"amount\": 1 }'' changes state on every retry, whereas ''{ \"status\": \"ACTIVE\" }'' is idempotent", "D": "PATCH is always safe"}'::jsonb, 'C', 'Unlike PUT, PATCH''s idempotency depends on the patch semantics.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000077'::uuid, 'What is the difference between ''301 Moved Permanently'' / ''302 Found'' vs ''307 Temporary Redirect'' / ''308 Permanent Redirect''?', '{"A": "307 and 308 strictly forbid changing the HTTP method (e.g., POST stays POST), whereas historical clients often rewrote POST to GET on 301/302", "B": "301 only works for images", "C": "There is no difference", "D": "307 is permanent"}'::jsonb, 'A', 'Use 307/308 when redirecting non-GET API requests so the HTTP method and body are preserved.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000076'::uuid, 'Why is a ''GET'' request with a JSON request body strongly discouraged even if the HTTP/1.1 grammar doesn''t strictly forbid framing it?', '{"A": "JSON cannot be parsed on GET", "B": "Spring Boot crashes", "C": "GET bodies are unencrypted", "D": "Many proxies, CDNs, load balancers, and client libraries (like browser Fetch) reject or strip GET bodies and caches ignore them"}'::jsonb, 'D', 'GET semantics define no meaning for a payload; use query parameters or POST for complex search payloads.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000078'::uuid, 'When DELETE is called a second time on an already-deleted resource, is returning 204/200 or 404 still compatible with HTTP idempotency?', '{"A": "Returning 404 breaks idempotency", "B": "DELETE is not idempotent", "C": "Yes! Idempotency refers to the resulting SERVER STATE (resource remains absent), not necessarily returning the identical status code", "D": "No, it must return 200"}'::jsonb, 'C', 'Both responses reflect an idempotent server state where the resource does not exist.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'http-methods-status-codes'), '70000000-0000-0000-0000-000000000077'::uuid, 'Why might an API intentionally return ''404 Not Found'' instead of ''403 Forbidden'' when a user requests another user''s private resource ID?', '{"A": "To prevent ID enumeration/existence leakage (confirming to an attacker that the ID exists)", "B": "Spring Security requires 404", "C": "404 is faster", "D": "403 is deprecated"}'::jsonb, 'A', 'Returning 404 hides whether a private resource exists at all.', 'ADVANCED', TRUE);

-- Skill: authentication-authorization
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000079'::uuid, 'What is the difference between hashing and encryption for storing passwords?', '{"A": "Hashing is one-way (irreversible); encryption is two-way (can be decrypted with a key)", "B": "Hashing is only for usernames", "C": "Encryption is one-way; hashing is reversible", "D": "They are identical"}'::jsonb, 'A', 'Passwords must be one-way hashed (never encrypted or plaintext) so even DB leaks don''t expose them.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000079'::uuid, 'Why is a unique random ''salt'' added to each user''s password before hashing?', '{"A": "To make passwords shorter", "B": "To speed up login", "C": "To ensure identical passwords produce different hashes and defeat precomputed rainbow tables", "D": "To replace HTTPS"}'::jsonb, 'C', 'Salting forces attackers to crack each password hash individually.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000080'::uuid, 'In traditional session-based authentication, what is stored in the user''s browser cookie?', '{"A": "The user''s plaintext password", "B": "The BCrypt salt", "C": "An opaque random session ID referencing server-side session state", "D": "The entire database row"}'::jsonb, 'C', 'The cookie carries only an opaque session identifier; user data stays on the server.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000081'::uuid, 'What are the three Base64Url-encoded parts of a JWT (JSON Web Token) separated by dots?', '{"A": "Header.Payload.Signature", "B": "Username.Password.Role", "C": "Method.Path.Body", "D": "Salt.Hash.Expiry"}'::jsonb, 'A', 'A compact JWS JWT has Header (alg/typ), Payload (claims), and Signature.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000082'::uuid, 'Why do systems pair a short-lived Access Token with a longer-lived Refresh Token?', '{"A": "To keep the stateless access token exposure window small while letting users stay logged in without re-entering passwords", "B": "Refresh tokens cannot be revoked", "C": "To double the payload size", "D": "Because access tokens cannot carry user IDs"}'::jsonb, 'A', 'If an access token leaks, it expires quickly; refresh tokens can be revoked server-side.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000083'::uuid, 'What is the difference between Authentication (AuthN) and Authorization (AuthZ)?', '{"A": "Authentication verifies who the user is; Authorization verifies what actions/resources that user is allowed to access", "B": "They are identical", "C": "Authentication is RBAC", "D": "Authorization comes before Authentication"}'::jsonb, 'A', 'AuthN = identity (401 on failure); AuthZ = permissions (403 on failure).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000079'::uuid, 'Which password-hashing algorithm is specifically designed for passwords with configurable work factor (cost)?', '{"A": "SHA-256", "B": "BCrypt (or Argon2)", "C": "MD5", "D": "CRC32"}'::jsonb, 'B', 'MD5 and plain SHA-256 are far too fast for passwords; BCrypt/Argon2 are deliberately slow and salted.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000083'::uuid, 'What does RBAC stand for?', '{"A": "Refresh Bearer Access Cookie", "B": "Role-Based Access Control", "C": "Random Binary Auth Check", "D": "Remote Backend API Client"}'::jsonb, 'B', 'RBAC assigns permissions to roles (e.g., USER, ADMIN) and roles to users.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000079'::uuid, 'Why are fast cryptographic hashes like SHA-256 dangerous for password storage even with a salt?', '{"A": "GPUs can compute billions of SHA-256 hashes per second, making brute-force cracking trivial", "B": "SHA-256 is reversible", "C": "SHA-256 cannot hash symbols", "D": "Salts don''t work with SHA-256"}'::jsonb, 'A', 'Password hashing requires memory-hard/slow KDFs (Argon2id, BCrypt, scrypt).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000080'::uuid, 'Compare storing a JWT in browser ''localStorage'' vs an ''HttpOnly; Secure; SameSite'' cookie.', '{"A": "localStorage is readable by any JavaScript (vulnerable to XSS theft); HttpOnly cookies cannot be read by JS (but need CSRF protection)", "B": "Both are immune to XSS", "C": "HttpOnly cookies are readable by document.cookie", "D": "localStorage is invisible to JavaScript"}'::jsonb, 'A', 'HttpOnly cookies protect tokens from XSS exfiltration; localStorage is exposed to any XSS script.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000081'::uuid, 'Is the Payload of a standard signed JWT (JWS) encrypted or merely Base64Url-encoded?', '{"A": "Merely Base64Url-encoded—anyone with the token can decode and read claims, so never put secrets in a JWS payload", "B": "Hashed with BCrypt", "C": "Compressed only", "D": "Encrypted with AES"}'::jsonb, 'A', 'Signature guarantees integrity/authenticity, NOT confidentiality; use JWE if payload confidentiality is needed.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000081'::uuid, 'Which standard JWT claims represent Subject, Issued-At, and Expiration Time?', '{"A": "usr, time, end", "B": "sub, iat, exp", "C": "aud, key, sig", "D": "id, start, ttl"}'::jsonb, 'B', 'RFC 7519 defines sub (subject), iat (issued at), exp (expiration), iss (issuer), jti (JWT ID).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000082'::uuid, 'What is Refresh Token Rotation?', '{"A": "Rotating HTTPS certificates", "B": "Issuing a brand-new refresh token on every refresh call and invalidating the previous one", "C": "Reusing the same refresh token forever", "D": "Changing the user''s password monthly"}'::jsonb, 'B', 'Rotation detects token reuse/theft: if a previously rotated token is replayed, the server can revoke the entire token family.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000082'::uuid, 'Why is revoking a stateless JWT Access Token before its ''exp'' time difficult?', '{"A": "Signatures change every second", "B": "JWTs have no expiration", "C": "Because stateless verification only checks the cryptographic signature and expiry without hitting a central store", "D": "Clients cannot delete headers"}'::jsonb, 'C', 'Immediate revocation requires a short expiry, a token denylist (Redis), or server-side sessions.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000083'::uuid, 'In Spring Security, what is the difference between ''.hasRole("ADMIN")'' and ''.hasAuthority("ROLE_ADMIN")''?', '{"A": "hasAuthority prepends ''AUTH_''", "B": "hasRole checks usernames", "C": "hasRole(\"ADMIN\") automatically prepends the ''ROLE_'' prefix; hasAuthority checks the exact string", "D": "They are completely unrelated"}'::jsonb, 'C', 'Mixing up the ''ROLE_'' prefix is a classic Spring Security configuration bug.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000080'::uuid, 'What is Session Fixation, and how do frameworks prevent it?', '{"A": "An attacker forces a known session ID onto a victim before login; prevented by rotating/generating a fresh session ID immediately upon authentication", "B": "Using BCrypt", "C": "Session never expires", "D": "Storing sessions in URL"}'::jsonb, 'A', 'Spring Security rotates the session ID on login by default.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000081'::uuid, 'Why must a JWT verifier explicitly enforce the expected signing algorithm (e.g., HS256 or RS256) rather than trusting the token''s ''alg'' header blindly?', '{"A": "Because Base64 requires it", "B": "To skip signature checks", "C": "To make tokens shorter", "D": "To prevent ''alg: none'' or RS256-to-HS256 key-confusion attacks"}'::jsonb, 'D', 'Modern JWT libraries (like JJWT 0.12+) require specifying the verification key/algorithm explicitly.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000083'::uuid, 'Why must backend endpoints ALSO check resource ownership (e.g., ''attempt.userId == currentUser.id''), not just RBAC role?', '{"A": "Spring Security doesn''t support roles", "B": "To prevent IDOR / BOLA (Broken Object Level Authorization) where User A accesses User B''s attempt by guessing its UUID", "C": "UUIDs are sequential", "D": "RBAC doesn''t work with POST"}'::jsonb, 'B', 'MilestoneService.validateOwnership() enforces object-level authorization alongside role checks.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000081'::uuid, 'Compare symmetric JWT signing (HS256) vs asymmetric JWT signing (RS256/ES256) in a multi-service system.', '{"A": "RS256 cannot be verified offline", "B": "HS256 uses public keys", "C": "HS256 is asymmetric", "D": "HS256 shares one secret key across issuer and all verifiers; RS256/ES256 lets only the Auth service hold the private key while any service verifies using the public JWKS"}'::jsonb, 'D', 'Asymmetric signing via JWKS limits private-key exposure to the token issuer.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000082'::uuid, 'How should Refresh Tokens be stored in a PostgreSQL table for maximum security?', '{"A": "Plaintext token string", "B": "Encrypt with Base64", "C": "Store a cryptographic hash (e.g., SHA-256) of the opaque random refresh token, just like API keys, so a DB read leak cannot be replayed", "D": "Store in localStorage only"}'::jsonb, 'C', 'Hashing high-entropy random tokens in the DB prevents stolen DB backups from granting access.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000079'::uuid, 'Why does BCrypt have a maximum password input length (72 bytes) and what risk exists if an app forgets this?', '{"A": "BCrypt rejects >8 chars", "B": "72 bytes is the salt", "C": "BCrypt crashes on UTF-8", "D": "BCrypt silently truncates inputs past 72 bytes, so two long passwords sharing the first 72 bytes match (unless pre-hashed or length-validated)"}'::jsonb, 'D', 'Be aware of the 72-byte limit when designing password policies.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000083'::uuid, 'How does OAuth 2.0 Authorization Code Flow with PKCE protect public clients (SPAs/mobile) compared to the deprecated Implicit Flow?', '{"A": "PKCE removes HTTPS", "B": "PKCE embeds the client_secret in JS", "C": "Implicit Flow is more secure", "D": "Tokens aren''t exposed in URL fragments; PKCE binds the authorization code to a dynamically generated code_verifier/code_challenge"}'::jsonb, 'D', 'PKCE prevents authorization-code interception attacks without requiring a confidential client secret.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000080'::uuid, 'Why should logout invalidate the refresh token / session server-side rather than only deleting the token on the frontend?', '{"A": "HTTP forbids client deletion", "B": "Cookies auto-restore", "C": "Frontend cannot delete localStorage", "D": "Deleting from client storage alone leaves an already-copied token valid until expiry"}'::jsonb, 'D', 'True logout must revoke server-side refresh/session state.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'authentication-authorization'), '70000000-0000-0000-0000-000000000083'::uuid, 'What is the ''Timing Attack'' risk in naive token/signature comparison (''a.equals(b)'') and how is it prevented?', '{"A": "Use == instead", "B": "Early-exit string comparison leaks how many leading bytes matched via response time; prevent with constant-time comparison (MessageDigest.isEqual)", "C": "equals() throws NPE", "D": "Timing attacks only affect SQL"}'::jsonb, 'B', 'Constant-time comparison takes identical CPU time regardless of where a mismatch occurs.', 'ADVANCED', TRUE);

-- Skill: spring-framework-ioc
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000084'::uuid, 'What does IoC (Inversion of Control) mean in the Spring Framework?', '{"A": "Classes manually instantiate all their dependencies with ''new''", "B": "SQL queries control Java compilation", "C": "The Spring container creates, configures, wires, and manages object lifecycles instead of the application code doing it", "D": "Control flows from database to browser"}'::jsonb, 'C', 'IoC inverts responsibility for object creation and dependency wiring to the container.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000084'::uuid, 'What is a ''Spring Bean''?', '{"A": "A Maven plugin", "B": "An object that is instantiated, assembled, and managed by the Spring IoC container", "C": "Any Java class with getters/setters", "D": "A PostgreSQL table"}'::jsonb, 'B', 'Spring Beans are container-managed objects registered via annotations or configuration.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000085'::uuid, 'What is ''BeanFactory'' in Spring?', '{"A": "A JUnit runner", "B": "A annotation for REST controllers", "C": "A database factory", "D": "The root interface for accessing a Spring IoC container, providing basic bean management and lazy instantiation"}'::jsonb, 'D', 'BeanFactory is Spring''s foundational container interface.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000086'::uuid, 'How does ''ApplicationContext'' relate to ''BeanFactory''?', '{"A": "ApplicationContext extends BeanFactory and adds enterprise features (events, i18n, AOP, eager singleton init)", "B": "They are unrelated", "C": "BeanFactory extends ApplicationContext", "D": "ApplicationContext is deprecated"}'::jsonb, 'A', 'ApplicationContext is the full-featured IoC container used in almost all Spring applications.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000086'::uuid, 'Which annotation runs a method right after a Spring Bean''s dependencies have been injected?', '{"A": "@BeforeAll", "B": "@PostConstruct", "C": "@PreDestroy", "D": "@Autowired"}'::jsonb, 'B', '@PostConstruct (from jakarta.annotation) executes once after dependency injection completes.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000087'::uuid, 'Which annotation runs a cleanup method right before a singleton Spring Bean is destroyed on shutdown?', '{"A": "@PostConstruct", "B": "@PreDestroy", "C": "@Bean", "D": "@Override"}'::jsonb, 'B', '@PreDestroy marks a lifecycle callback invoked during container shutdown.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000084'::uuid, 'Why is IoC beneficial for unit testing?', '{"A": "IoC disables JUnit", "B": "Because dependencies are injected by the container, tests can easily pass mock or stub implementations", "C": "IoC compiles faster", "D": "IoC writes tests automatically"}'::jsonb, 'B', 'Decoupled dependencies make isolated unit testing with Mockito straightforward.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000087'::uuid, 'When does ApplicationContext instantiate ''singleton''-scoped beans by default?', '{"A": "Only on first HTTP request", "B": "Only when @Lazy is added", "C": "Eagerly at application startup", "D": "Never"}'::jsonb, 'C', 'Eager startup instantiation catches configuration/wiring errors immediately at boot time.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000085'::uuid, 'What is the key instantiation difference between a basic ''BeanFactory'' and ''ApplicationContext''?', '{"A": "ApplicationContext is lazy", "B": "BeanFactory lazily creates beans only on first getBean(); ApplicationContext pre-instantiates non-lazy singleton beans at startup", "C": "There is no difference", "D": "BeanFactory supports AOP automatically"}'::jsonb, 'B', 'ApplicationContext''s eager initialization fails fast on misconfigured beans.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000086'::uuid, 'Name three capabilities ApplicationContext provides beyond BeanFactory.', '{"A": "Docker builds, Git commits", "B": "Event publication (ApplicationEventPublisher), internationalization (MessageSource), and automatic BeanPostProcessor / AOP registration", "C": "Bytecode obfuscation", "D": "SQL parsing, HTML rendering, DNS lookup"}'::jsonb, 'B', 'ApplicationContext integrates resource loading, i18n, eventing, and BeanPostProcessors.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000087'::uuid, 'What is the correct high-level order of Spring Bean initialization lifecycle?', '{"A": "Instantiation (Constructor) -> Dependency Injection -> BeanPostProcessor.postProcessBeforeInitialization -> @PostConstruct / InitializingBean -> postProcessAfterInitialization", "B": "AOP Proxy -> Constructor", "C": "@PreDestroy -> Constructor", "D": "@PostConstruct -> Constructor -> Dependency Injection"}'::jsonb, 'A', 'Dependencies are injected before @PostConstruct runs, and AOP proxies are typically wrapped in postProcessAfterInitialization.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000087'::uuid, 'What does a ''BeanPostProcessor'' allow Spring (and frameworks) to do?', '{"A": "Intercept and wrap/modify every bean before and after initialization (e.g., creating @Transactional / @Async proxies)", "B": "Replace Maven", "C": "Delete beans from source code", "D": "Run SQL migrations"}'::jsonb, 'A', 'BeanPostProcessors power @Autowired, @Value, and AOP proxy creation.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000087'::uuid, 'What does a ''BeanFactoryPostProcessor'' modify compared to a ''BeanPostProcessor''?', '{"A": "BeanFactoryPostProcessor modifies bean DEFINITIONS (metadata) before beans are instantiated; BeanPostProcessor modifies bean INSTANCES", "B": "BeanPostProcessor runs before definitions are loaded", "C": "They modify the same thing", "D": "BeanFactoryPostProcessor runs on shutdown"}'::jsonb, 'A', 'For example, PropertySourcesPlaceholderConfigurer resolves $' || '{...} placeholders in bean definitions via BeanFactoryPostProcessor.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000084'::uuid, 'What happens if you mark a bean with ''@Lazy''?', '{"A": "Spring defers creating the bean until it is first requested or injected into an eagerly initialized bean", "B": "It becomes prototype-scoped", "C": "It runs on a background thread", "D": "It is never created"}'::jsonb, 'A', '@Lazy delays initialization, useful for heavy optional beans or breaking certain circular dependencies.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000086'::uuid, 'How does Spring''s ''ApplicationEventPublisher'' support loose coupling inside an application?', '{"A": "It replaces PostgreSQL triggers", "B": "Beans publish domain events and @EventListener beans react without the publisher knowing the listeners", "C": "It creates threads automatically", "D": "It sends HTTP webhooks"}'::jsonb, 'B', 'In-process domain events decouple side effects like notifications or audit logging.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000085'::uuid, 'What happens if a ''prototype''-scoped bean defines a ''@PreDestroy'' method?', '{"A": "It runs immediately after construction", "B": "Spring calls @PreDestroy on shutdown", "C": "Spring does NOT track prototype beans after creation and does NOT invoke @PreDestroy on them", "D": "Compile error"}'::jsonb, 'C', 'For prototype beans, the client owns cleanup; Spring only manages destruction callbacks for singletons.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000087'::uuid, 'Why is ''@Transactional'' NOT active if called directly inside a ''@PostConstruct'' method?', '{"A": "@Transactional only works in controllers", "B": "PostgreSQL is not started yet", "C": "Spring forbids @PostConstruct", "D": "PostConstruct runs BEFORE BeanPostProcessor.postProcessAfterInitialization wraps the bean in its AOP transaction proxy"}'::jsonb, 'D', 'During @PostConstruct, the target object isn''t proxied yet; use ApplicationReadyEvent or CommandLineRunner instead.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000084'::uuid, 'What is a circular dependency in Spring IoC (Bean A -> Bean B -> Bean A) with constructor injection?', '{"A": "Resolved silently", "B": "Fails at startup with BeanCurrentlyInCreationException because neither can be constructed first", "C": "Creates infinite beans", "D": "Ignored by Spring Boot"}'::jsonb, 'B', 'Spring Boot 2.6+ also disallows circular references by default; refactor shared logic into a third bean.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000087'::uuid, 'Why does Spring''s CGLIB/JDK dynamic proxy for ''@Transactional'' or ''@Async'' fail when a bean calls its own method (''this.innerMethod()'')?', '{"A": "Private methods are proxied instead", "B": "CGLIB disables @Transactional", "C": "Self-invocation bypasses the outer AOP proxy and calls the raw target method directly", "D": "this is null inside beans"}'::jsonb, 'C', 'Interceptors only run when calls pass through the Spring proxy reference, not internal ''this.'' calls.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000086'::uuid, 'How does ''TransactionTemplate'' or ''@TransactionalEventListener(phase = AFTER_COMMIT)'' solve post-commit side effects cleanly?', '{"A": "It disables rollbacks", "B": "It runs before BEGIN", "C": "It delays firing the listener until the database transaction actually commits, preventing phantom notifications if rollback occurs", "D": "It locks the table"}'::jsonb, 'C', 'AFTER_COMMIT ensures emails/events aren''t sent for rolled-back transactions.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000085'::uuid, 'What is ''FactoryBean<T>'' in Spring vs a normal ''@Bean'' factory method?', '{"A": "They are identical", "B": "A FactoryBean<T> is a bean that itself acts as a factory: getBean(\"myName\") returns getObject() (T), while getBean(\"&myName\") returns the FactoryBean itself", "C": "FactoryBean creates tables", "D": "FactoryBean is only for XML"}'::jsonb, 'B', 'Spring Data JPA uses FactoryBean internally to synthesize repository proxy implementations.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000087'::uuid, 'What is the difference between a JDK Dynamic Proxy and a CGLIB subclass proxy in Spring AOP?', '{"A": "CGLIB requires an interface", "B": "JDK Proxy works without interfaces", "C": "JDK Proxy requires an interface and uses reflection InvocationHandler; CGLIB subclasses the target class at runtime (cannot proxy final classes/methods)", "D": "CGLIB cannot proxy @Service"}'::jsonb, 'C', 'Spring Boot defaults to CGLIB (proxyTargetClass=true) so concrete classes without interfaces can be proxied.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000084'::uuid, 'How does Spring''s 3-level singleton cache resolve setter/field circular dependencies (when enabled) while constructor cycles still fail?', '{"A": "It deletes one bean", "B": "An early ObjectFactory reference is exposed in Level 3 cache after instantiation but before population, allowing the other bean to inject the unfinished reference", "C": "It uses ThreadLocal", "D": "It creates two instances"}'::jsonb, 'B', 'With constructors, instantiation itself cannot complete, so early reference caching cannot help.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-framework-ioc'), '70000000-0000-0000-0000-000000000086'::uuid, 'What is ''SmartLifecycle'' in Spring?', '{"A": "A Maven lifecycle", "B": "A replacement for @Entity", "C": "A lifecycle interface offering phased startup/shutdown ordering (getPhase()) and async stop callbacks", "D": "An annotation for DTOs"}'::jsonb, 'C', 'SmartLifecycle controls exact startup/shutdown order across infrastructure beans (e.g., message consumers, servers).', 'ADVANCED', TRUE);

-- Skill: dependency-injection-spring-beans
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000088'::uuid, 'What are the three ways to perform Dependency Injection in Spring?', '{"A": "Static, Final, Abstract injection", "B": "SQL, HTTP, JSON injection", "C": "Loop, Switch, Try injection", "D": "Constructor injection, Setter injection, and Field injection"}'::jsonb, 'D', 'Spring supports constructor, setter, and field (@Autowired on field) injection.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000088'::uuid, 'Which Dependency Injection style is strongly recommended by the Spring team for required dependencies?', '{"A": "Reflection in main()", "B": "Static setter injection", "C": "Field injection (@Autowired on private field)", "D": "Constructor injection"}'::jsonb, 'D', 'Constructor injection allows final fields, guarantees valid non-null state, and simplifies unit testing without a Spring context.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000089'::uuid, 'What is the difference between ''@Component'' and ''@Bean''?', '{"A": "@Component is placed on your own class for component scanning; @Bean is placed on a method inside a @Configuration class (often for third-party/custom-configured objects)", "B": "@Component cannot be injected", "C": "@Bean goes on classes; @Component goes on methods", "D": "They are identical"}'::jsonb, 'A', 'You use @Bean when you don''t own the class source (e.g., PasswordEncoder, ObjectMapper) or need programmatic setup.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000089'::uuid, 'Which stereotype annotations are specializations of ''@Component''?', '{"A": "@Id and @Column", "B": "@Test and @Mock", "C": "@Service, @Repository, and @Controller/@RestController", "D": "@Entity and @Table"}'::jsonb, 'C', 'All three are meta-annotated with @Component and carry semantic layer meaning (plus exception translation on @Repository).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000090'::uuid, 'What is the default scope of a Spring Bean?', '{"A": "prototype", "B": "singleton (one shared instance per Spring IoC container)", "C": "session", "D": "request"}'::jsonb, 'B', 'By default, Spring creates one singleton instance per bean definition per ApplicationContext.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000090'::uuid, 'What does ''@Scope("prototype")'' do?', '{"A": "Disables injection", "B": "Creates one instance per HTTP request", "C": "Creates a brand-new bean instance every time it is requested from the container", "D": "Creates one instance per JVM"}'::jsonb, 'C', 'Prototype scope produces a fresh instance per injection/getBean() call.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000091'::uuid, 'What is the role of the ''PasswordEncoder'' bean (e.g., BCryptPasswordEncoder) in Spring Security?', '{"A": "Validating emails", "B": "Encrypting JWTs", "C": "Hashing passwords on registration and verifying raw vs hashed passwords on login", "D": "Parsing HTTP headers"}'::jsonb, 'C', 'PasswordEncoder.encode() hashes passwords and matches() verifies login attempts safely.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000091'::uuid, 'What is ''AuthenticationManager'' in Spring Security?', '{"A": "A CORS filter", "B": "A React hook", "C": "A database table", "D": "The core interface that processes an Authentication request (such as username/password) by delegating to AuthenticationProviders"}'::jsonb, 'D', 'Login controllers/filters call authenticationManager.authenticate(...) to verify credentials.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000088'::uuid, 'If a Spring bean class has ONLY ONE constructor, is ''@Autowired'' required on that constructor?', '{"A": "Only with Lombok @RequiredArgsConstructor", "B": "Yes, always", "C": "Only for controllers", "D": "No; Spring 4.3+ automatically treats a single constructor as the injection point"}'::jsonb, 'D', 'Combining a single constructor with Lombok''s @RequiredArgsConstructor and ''private final'' fields is idiomatic Spring Boot.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000088'::uuid, 'Why is field injection (''@Autowired private UserRepo repo;'') discouraged?', '{"A": "Spring removed @Autowired", "B": "Fields cannot be final, dependencies are hidden, and unit tests require reflection or Spring context to populate them", "C": "Field injection is slower at runtime queries", "D": "Field injection throws NullPointerException at startup"}'::jsonb, 'B', 'Constructor injection enforces immutability and exposes tight coupling immediately if a constructor grows too large.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000088'::uuid, 'What exception does Spring throw if two beans implement the same interface (e.g., StripePayment and PaypalPayment) and you inject ''PaymentService'' without disambiguation?', '{"A": "ClassCastException", "B": "NullPointerException", "C": "BeanCreationNotAllowedException", "D": "NoUniqueBeanDefinitionException"}'::jsonb, 'D', 'Resolve ambiguity with ''@Qualifier("beanName")'' or ''@Primary''.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000089'::uuid, 'What extra behavior does ''@Repository'' add beyond ''@Component''?', '{"A": "Makes methods transactional", "B": "Creates database tables", "C": "Automatic SQL caching", "D": "PersistenceExceptionTranslationPostProcessor translates vendor-specific SQL/JPA exceptions into Spring''s unified DataAccessException hierarchy"}'::jsonb, 'D', '@Repository enables consistent data-access exception translation.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000089'::uuid, 'How does ''@Configuration'' differ from ''@Component'' when declaring ''@Bean'' methods inside it (full vs lite mode)?', '{"A": "They behave identically", "B": "@Configuration proxies the class via CGLIB so calling beanA() from beanB() returns the shared singleton bean; @Component lite mode calls the method directly creating a new instance", "C": "@Configuration disables singletons", "D": "@Component cannot have @Bean"}'::jsonb, 'B', 'proxyBeanMethods=true (default on @Configuration) ensures inter-bean method calls respect singleton scope.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000090'::uuid, 'What happens if you inject a ''prototype'' bean directly into a ''singleton'' bean?', '{"A": "A new prototype is created on every method call of the singleton", "B": "Compile error", "C": "Startup crash", "D": "The singleton receives ONE prototype instance at startup and reuses that same instance forever unless ObjectProvider/lookup is used"}'::jsonb, 'D', 'Injection into a singleton happens once at startup; use ObjectProvider<MyProto> to obtain a fresh instance per call.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000090'::uuid, 'What are ''request'' and ''session'' bean scopes used for?', '{"A": "Database transaction scopes", "B": "Web-aware scopes creating one bean instance per HTTP request or per HTTP session", "C": "CLI batch jobs", "D": "Thread pool scopes"}'::jsonb, 'B', 'Web scopes bind bean lifecycles to HTTP requests or sessions (using scoped proxies when injected into singletons).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000091'::uuid, 'How does ''DaoAuthenticationProvider'' verify a user''s login in Spring Security?', '{"A": "It queries JWT directly", "B": "It hashes the username", "C": "It loads UserDetails via UserDetailsService and checks the submitted password against the stored hash using PasswordEncoder.matches()", "D": "It bypasses the database"}'::jsonb, 'C', 'DaoAuthenticationProvider coordinates UserDetailsService + PasswordEncoder.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000091'::uuid, 'In Spring Security 6 / Boot 3+, how do you expose an ''AuthenticationManager'' bean for a custom ''/api/auth/login'' controller?', '{"A": "Extend WebSecurityConfigurerAdapter", "B": "Instantiate new ProviderManager() with no providers", "C": "Define a @Bean method accepting AuthenticationConfiguration and returning config.getAuthenticationManager()", "D": "Inject HttpServletRequest"}'::jsonb, 'C', 'WebSecurityConfigurerAdapter was removed in Spring Security 6; AuthenticationConfiguration exposes the configured AuthenticationManager.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000089'::uuid, 'What happens when you inject ''List<MyStrategy>'' into a Spring bean?', '{"A": "Startup error", "B": "Only injects @Primary", "C": "Spring automatically injects ALL active beans implementing MyStrategy (ordered by @Order if present)", "D": "Injects an empty list"}'::jsonb, 'C', 'Collection/Map injection makes implementing the Strategy pattern in Spring effortless.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000091'::uuid, 'Why is ''SecurityContextHolder'' stored in a ''ThreadLocal'' by default, and what happens if you spawn a raw ''new Thread(...)'' inside a controller?', '{"A": "ThreadLocal crashes the JVM", "B": "The child thread does NOT inherit the SecurityContext (getAuthentication() returns null) unless wrapped with DelegatingSecurityContextRunnable / @Async configuration", "C": "All users share one login", "D": "Spring copies it to all threads automatically"}'::jsonb, 'B', 'ThreadLocal isolates per-request authentication, requiring explicit propagation across async thread boundaries.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000090'::uuid, 'How does ''ObjectProvider<T>'' (or ''Provider<T>'') solve both prototype-in-singleton and optional/lazy dependency injection?', '{"A": "ObjectProvider delays bean lookup until getObject() / getIfAvailable() is called at runtime", "B": "It caches HTTP responses", "C": "It disables DI", "D": "It converts prototype to singleton"}'::jsonb, 'A', 'ObjectProvider gives programmatic, lazy, and optional access to beans without circularity or stale-prototype issues.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000088'::uuid, 'When a singleton bean has mutable instance state (e.g., ''private int counter = 0;''), why is that a concurrency bug in Spring Boot web apps?', '{"A": "Spring locks the bean per request", "B": "Tomcat runs single-threaded", "C": "Singletons cannot have int fields", "D": "Multiple concurrent HTTP worker threads share the single bean instance, causing race conditions on unsynchronized mutable fields"}'::jsonb, 'D', 'Spring singletons should be stateless (holding only injected final collaborators), or use thread-safe structures.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000091'::uuid, 'What does ''DelegatingPasswordEncoder'' (created by PasswordEncoderFactories.createDelegatingPasswordEncoder()) allow during password algorithm upgrades?', '{"A": "It stores plaintext passwords", "B": "It skips verification", "C": "It prefixes hashes with ''{bcrypt}'', ''{argon2}'', etc., allowing old BCrypt hashes to keep verifying while new passwords use an upgraded algorithm", "D": "It disables salt"}'::jsonb, 'C', 'Algorithm-prefixed hashes enable seamless zero-downtime password hash migrations.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000089'::uuid, 'What does ''@ConditionalOnMissingBean'' do when paired with ''@Bean'' in Spring Boot library/starter design?', '{"A": "Deletes existing beans", "B": "Registers the default bean ONLY if the user application hasn''t already defined its own bean of that type", "C": "Forces two beans", "D": "Throws an error if a bean is missing"}'::jsonb, 'B', 'It lets frameworks provide sensible defaults that applications can override cleanly.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'dependency-injection-spring-beans'), '70000000-0000-0000-0000-000000000091'::uuid, 'In a custom ''OncePerRequestFilter'' for JWT authentication, why do we register it via SecurityFilterChain (''addFilterBefore'') AND why might marking it ''@Component'' cause it to run TWICE unless careful?', '{"A": "OncePerRequestFilter always runs twice", "B": "Spring Boot auto-registers any Filter @Bean with the outer Servlet container AND SecurityFilterChain registers it inside the security filter chain; either don''t make it a @Component or wrap in FilterRegistrationBean(enabled=false)", "C": "JWTs require two passes", "D": "Servlet container ignores filters"}'::jsonb, 'B', 'OncePerRequestFilter still runs once per dispatch, or you can avoid @Component on the filter or disable Servlet auto-registration.', 'ADVANCED', TRUE);

-- Skill: spring-boot-auto-configuration
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
