INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000093'::uuid, 'Which composite annotation is typically placed on the main Spring Boot application class?', '{"A": "@SpringBootApplication", "B": "@BeanFactory", "C": "@WebServlet", "D": "@EnableSQL"}'::jsonb, 'A', '@SpringBootApplication combines @SpringBootConfiguration, @EnableAutoConfiguration, and @ComponentScan.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000094'::uuid, 'What is the default file name and location Spring Boot reads for externalized configuration properties?', '{"A": "src/main/java/config.txt", "B": "src/main/resources/application.properties (or application.yml)", "C": "pom.xml", "D": "db/migration/config.sql"}'::jsonb, 'B', 'Spring Boot loads application.properties / application.yml from the classpath root (src/main/resources).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000095'::uuid, 'In modern Spring Boot (Spring Security 6+), which bean configures HTTP endpoint authorization rules and filters?', '{"A": "DispatcherServlet", "B": "EntityManager", "C": "SecurityFilterChain", "D": "WebSecurityConfigurerAdapter"}'::jsonb, 'C', 'A @Bean SecurityFilterChain method configures HttpSecurity rules declaratively.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
