INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000093'::uuid, 'How does Spring Boot Auto-Configuration decide whether to configure a DataSource or Flyway bean automatically?', '{"A": "It configures every possible library unconditionally", "B": "By scanning all Git commits", "C": "By evaluating @Conditional annotations (such as @ConditionalOnClass, @ConditionalOnMissingBean, @ConditionalOnProperty)", "D": "By reading React files"}'::jsonb, 'C', 'Conditionals inspect classpath classes, existing user beans, and properties before registering auto-configured beans.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000094'::uuid, 'How does ''@ConfigurationProperties(prefix = "app.jwt")'' improve upon ''@Value("$' || '{app.jwt.secret}")''?', '{"A": "@Value only reads ints", "B": "It binds a group of properties into a strongly-typed POJO/record with IDE autocomplete and JSR-303 @Validated checks", "C": "@Value cannot read application.properties", "D": "@ConfigurationProperties bypasses Spring"}'::jsonb, 'B', '@ConfigurationProperties enables structured, validated configuration binding.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000095'::uuid, 'Why do stateless JWT REST APIs configure ''sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))''?', '{"A": "So Spring Security never creates or uses HTTP sessions (JSESSIONID), authenticating each request purely from its token", "B": "To disable authentication", "C": "To enable CSRF cookies", "D": "To cache SQL queries"}'::jsonb, 'A', 'STATELESS policy guarantees no server-side HttpSession is created.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000096'::uuid, 'When is disabling CSRF protection (''csrf.disable()'') acceptable in a Spring Boot API?', '{"A": "Always, even for cookie-based sessions", "B": "Never", "C": "Only in production", "D": "When the API is purely stateless and authenticates via Authorization: Bearer headers (not browser cookies)"}'::jsonb, 'D', 'Browsers do not automatically attach Authorization headers cross-origin, so pure Bearer-token APIs aren''t vulnerable to cookie CSRF.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000093'::uuid, 'What does running a Spring Boot app with ''--debug'' (or ''debug=true'') show regarding auto-configuration?', '{"A": "Bytecode of every class", "B": "All user passwords", "C": "Only SQL errors", "D": "The Condition Evaluation Report listing which auto-configurations matched (Positive) and which did not (Negative) and why"}'::jsonb, 'D', 'The Conditions Evaluation Report is the fastest way to debug why a bean did or didn''t auto-configure.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
