INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000095'::uuid, 'In ''SecurityFilterChain'', what is the difference between ''.permitAll()'' and ''WebSecurityCustomizer.ignoring()''?', '{"A": "permitAll() still runs the security filter chain (allowing CORS, headers, etc.) and authorizes anonymous access; ignoring() bypasses Spring Security completely", "B": "permitAll() blocks requests", "C": "ignoring() enables JWT", "D": "They are identical"}'::jsonb, 'A', 'Spring recommends permitAll() over ignoring() for API endpoints so security headers and CORS still apply.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000094'::uuid, 'In Spring Boot property precedence, which overrides the other: ''application.properties'' inside the JAR vs OS environment variables?', '{"A": "JAR application.properties wins", "B": "Env vars are ignored", "C": "OS environment variables (and command-line arguments) override packaged application.properties", "D": "They merge randomly"}'::jsonb, 'C', 'Externalized env vars/CLI args have higher precedence, enabling 12-factor deployments without rebuilding the JAR.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000096'::uuid, 'Why must CORS be configured inside Spring Security (''.cors(Customizer.withDefaults())'') when Spring Security is on the classpath?', '{"A": "CORS only works on GET", "B": "WebMvcConfigurer deletes CORS", "C": "Tomcat blocks OPTIONS", "D": "Because Spring Security''s FilterChain runs BEFORE Spring MVC''s @CrossOrigin/WebMvcConfigurer; without Security CORS, preflight OPTIONS requests get rejected with 401/403"}'::jsonb, 'D', 'Security filters intercept OPTIONS preflight first unless Security delegates to the CorsConfigurationSource bean.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000092'::uuid, 'What does ''spring-boot-starter-actuator'' add to a backend service?', '{"A": "A Flyway replacement", "B": "An OAuth server", "C": "A frontend UI", "D": "Production-ready operational endpoints like /actuator/health, /actuator/info, and /actuator/metrics"}'::jsonb, 'D', 'Actuator exposes health probes and Micrometer metrics for monitoring and Kubernetes/LB readiness.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000093'::uuid, 'In Spring Boot 3 / 4, where are auto-configuration classes registered instead of the legacy ''spring.factories''?', '{"A": "application.properties", "B": "pom.xml", "C": "META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports", "D": "WEB-INF/web.xml"}'::jsonb, 'C', 'Spring Boot 2.7/3.0+ moved auto-config registration to AutoConfiguration.imports and @AutoConfiguration.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000095'::uuid, 'How can an application define TWO separate ''SecurityFilterChain'' beans (e.g., one for ''/api/**'' stateless JWT and another for ''/admin/**'' form/session)?', '{"A": "Use @Primary only", "B": "Put both in one controller", "C": "Spring forbids two SecurityFilterChains", "D": "Use ''@Order(1)'' with ''http.securityMatcher(\"/api/**\")'' on the first chain and ''@Order(2)'' as catch-all on the second"}'::jsonb, 'D', 'securityMatcher scopes each chain cleanly by path/request matcher and @Order determines evaluation precedence.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000094'::uuid, 'What is the risk of using ''spring.jpa.hibernate.ddl-auto=update'' alongside Flyway in production?', '{"A": "Hibernate stops working", "B": "Hibernate may alter schema independently of Flyway migrations, causing drift, checksum issues, or accidental data loss", "C": "Flyway deletes the database", "D": "update is read-only"}'::jsonb, 'B', 'In production with Flyway, set ''ddl-auto=validate'' (or ''none'') so Flyway owns all DDL changes.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000093'::uuid, 'Why should ''@AutoConfiguration'' ordering (''before'' / ''after'') matter when writing custom starters (e.g., running after DataSourceAutoConfiguration)?', '{"A": "Because @ConditionalOnBean(DataSource.class) fails if your auto-config evaluates BEFORE DataSourceAutoConfiguration registers the DataSource bean", "B": "Alphabetical order is always enough", "C": "Maven sorts classes", "D": "Order only affects controllers"}'::jsonb, 'A', '@ConditionalOnBean depends on evaluation order, so auto-configs must declare after/before relationships.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000095'::uuid, 'In Spring Security, why does a failed authentication inside a custom filter NOT automatically trigger ''@RestControllerAdvice''?', '{"A": "Filters cannot throw exceptions", "B": "@RestControllerAdvice only catches 404", "C": "Servlet Filters execute BEFORE DispatcherServlet; filter exceptions are handled by AuthenticationEntryPoint / AccessDeniedHandler (or HandlerExceptionResolver), not @ControllerAdvice", "D": "Spring Security disables JSON"}'::jsonb, 'C', 'Configure custom AuthenticationEntryPoint and AccessDeniedHandler in SecurityFilterChain to return clean JSON 401/403 responses.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-boot-auto-configuration'), '70000000-0000-0000-0000-000000000096'::uuid, 'Why is using ''allowedOriginPatterns("http://localhost:*")'' with ''allowCredentials(true)'' valid in Spring Security CORS, whereas ''allowedOrigins("*")'' is rejected?', '{"A": "allowedOriginPatterns dynamically echoes the matched request Origin header in Access-Control-Allow-Origin instead of literal ''*'', satisfying the CORS spec when credentials are enabled", "B": "Credentials require CSRF disabled", "C": "Spring Boot blocks localhost", "D": "allowedOrigins(*) only allows HTTPS"}'::jsonb, 'A', 'Browsers reject literal ''*'' with Allow-Credentials: true; pattern matching safely echoes specific allowed origins.', 'ADVANCED', TRUE);

-- Skill: spring-data-jpa-hibernate
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000097'::uuid, 'Which annotation marks a Java class as a JPA database entity?', '{"A": "@Repository", "B": "@Entity", "C": "@Component", "D": "@Service"}'::jsonb, 'B', '@Entity maps a Java class to a relational database table (customized with @Table).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000097'::uuid, 'Why does JPA require every ''@Entity'' class to have a no-argument constructor (public or protected)?', '{"A": "Because Java forbids parameterized constructors", "B": "To make fields final", "C": "So Hibernate can instantiate entity objects via reflection when loading rows from the DB", "D": "For JSON serialization only"}'::jsonb, 'C', 'Hibernate uses reflection and proxies requiring a no-arg constructor (protected is sufficient).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000098'::uuid, 'What does extending ''JpaRepository<MilestoneQuestion, UUID>'' give you automatically without writing implementation code?', '{"A": "Flyway migrations", "B": "CRUD methods (save, findById, findAll, delete), pagination, sorting, and derived query support", "C": "JWT tokens", "D": "REST endpoints automatically"}'::jsonb, 'B', 'Spring Data JPA generates the repository proxy implementation at startup.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000098'::uuid, 'What is a Spring Data JPA ''derived query method''?', '{"A": "A stored procedure", "B": "A method whose SQL/JPQL is automatically generated from its method name (e.g., findBySkillIdAndIsActiveTrue)", "C": "A native SQL file", "D": "A constructor"}'::jsonb, 'B', 'Spring Data parses method prefixes (findBy, countBy, existsBy) and property paths into queries.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000099'::uuid, 'In a bidirectional ''@OneToMany'' / ''@ManyToOne'' relationship, which side normally owns the foreign key column in the database?', '{"A": "The @OneToMany (parent) side", "B": "Neither side", "C": "Both sides", "D": "The @ManyToOne (child) side using @JoinColumn"}'::jsonb, 'D', 'The ''many'' table holds the FK column; the ''one'' side uses mappedBy.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000100'::uuid, 'What is the key difference between JPQL and a native SQL query (''nativeQuery = true'') in ''@Query''?', '{"A": "Native SQL cannot use parameters", "B": "JPQL queries Entity class and Java field names; native SQL queries actual database table and column names", "C": "They are identical", "D": "JPQL runs in the browser"}'::jsonb, 'B', 'JPQL is object-oriented and database-independent; native SQL uses PostgreSQL-specific syntax directly.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000101'::uuid, 'What is the default fetch type in JPA for ''@ManyToOne'' vs ''@OneToMany''?', '{"A": "@ManyToOne: LAZY; @OneToMany: EAGER", "B": "Both are LAZY", "C": "@ManyToOne: EAGER; @OneToMany: LAZY", "D": "Both are EAGER"}'::jsonb, 'C', 'To-one defaults to EAGER (though LAZY is usually preferred!) and to-many collections default to LAZY.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000097'::uuid, 'Which annotation specifies the primary key field of a JPA entity?', '{"A": "@Key", "B": "@Id", "C": "@Column(pk=true)", "D": "@Primary"}'::jsonb, 'B', '@Id marks the primary key attribute (often paired with @GeneratedValue).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000097'::uuid, 'Why is using Lombok ''@Data'' or ''@EqualsAndHashCode'' (all fields) on ''@Entity'' classes dangerous?', '{"A": "toString/equals/hashCode can trigger lazy-loading queries, cause StackOverflowError on bidirectional relations, or break Set membership when id changes from null on persist", "B": "JPA forbids getters", "C": "It deletes @Id", "D": "Lombok doesn''t work with Java 21"}'::jsonb, 'A', 'Use @Getter/@Setter on entities and carefully implement equals/hashCode (e.g., on business key or class-safe id) instead of @Data.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000098'::uuid, 'How does Hibernate ''dirty checking'' save changes inside a ''@Transactional'' method without calling repository.save() explicitly?', '{"A": "It requires nativeQuery", "B": "Dirty checking only works on DELETE", "C": "Managed entities are tracked in the Persistence Context; on transaction flush/commit, Hibernate compares snapshots and automatically issues UPDATE SQL for modified fields", "D": "Hibernate rewrites bytecode to run JDBC on every setter"}'::jsonb, 'C', 'Any change to a managed entity inside an active transaction is flushed automatically.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000099'::uuid, 'What is the purpose of ''mappedBy'' in ''@OneToMany(mappedBy = "attempt")''?', '{"A": "It tells Hibernate the relationship is already owned by the ''attempt'' field on the child entity, preventing an extra join table", "B": "It sets ON DELETE CASCADE", "C": "It creates a new column", "D": "It enables EAGER loading"}'::jsonb, 'A', 'Omitting mappedBy on @OneToMany causes Hibernate to look for a third join table.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000100'::uuid, 'When writing an UPDATE or DELETE query in ''@Query'' in Spring Data JPA, which extra annotation is required?', '{"A": "@Modifying", "B": "@Cascade", "C": "@Entity", "D": "@Lazy"}'::jsonb, 'A', '@Modifying tells Spring Data JPA to execute executeUpdate() instead of a SELECT query.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000101'::uuid, 'What causes ''LazyInitializationException: could not initialize proxy - no Session''?', '{"A": "Missing @Id", "B": "PostgreSQL timeout", "C": "Using EAGER fetch", "D": "Accessing an uninitialized LAZY association after the Hibernate Session / @Transactional boundary has already closed"}'::jsonb, 'D', 'Fetch needed associations inside the transaction (JOIN FETCH / @EntityGraph) before mapping to DTOs.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000101'::uuid, 'What is the ''N+1 query problem'' in JPA/Hibernate?', '{"A": "Inserting N+1 rows", "B": "Running N transactions", "C": "Executing 1 query to fetch N parent entities, then N additional queries (one per parent) to load a lazy association", "D": "Adding 1 to primary keys"}'::jsonb, 'C', 'N+1 turns 1 list load of 100 items into 101 database round-trips.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000101'::uuid, 'How do you fix an N+1 query problem when loading parents with their children?', '{"A": "Use ''JOIN FETCH'' in JPQL or ''@EntityGraph'' on the repository query", "B": "Disable transactions", "C": "Use CrudRepository", "D": "Switch to @ManyToOne(fetch=EAGER)"}'::jsonb, 'A', 'JOIN FETCH or @EntityGraph loads parent and required children together in a single SQL query (note: EAGER alone still triggers N+1 in JPQL!).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000098'::uuid, 'How does ''JpaRepository.getReferenceById(id)'' differ from ''findById(id)''?', '{"A": "getReferenceById returns Optional", "B": "They are identical", "C": "findById executes a SELECT immediately; getReferenceById returns a lazy proxy without hitting the DB unless non-ID fields are accessed (useful when setting a FK)", "D": "findById is deprecated"}'::jsonb, 'C', 'getReferenceById avoids an unnecessary SELECT when you only need a FK reference.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000099'::uuid, 'What is the difference between JPA ''cascade = CascadeType.REMOVE'' and ''orphanRemoval = true''?', '{"A": "CascadeType.REMOVE sets FK to NULL", "B": "They are identical", "C": "orphanRemoval deletes the parent", "D": "CascadeType.REMOVE deletes children only when the parent entity itself is deleted; orphanRemoval = true ALSO deletes a child when removed from the parent''s collection"}'::jsonb, 'D', 'orphanRemoval treats child entities as completely owned by the parent''s collection.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000100'::uuid, 'Why should you ALWAYS use named/positional bind parameters ('':skillId'') in JPQL/SQL instead of string concatenation?', '{"A": "String concatenation is forbidden in Java", "B": "Bind parameters skip indexes", "C": "To prevent SQL/JPQL injection and enable query plan caching", "D": "Named parameters only work on UUID"}'::jsonb, 'C', 'Parameterized queries bind user input safely as data, never executable SQL.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000101'::uuid, 'What happens if you combine ''JOIN FETCH'' on a ''@OneToMany'' collection WITH ''Pageable'' (LIMIT/OFFSET) in Hibernate?', '{"A": "Hibernate logs HHH90003004 (''firstResult/maxResults specified with collection fetch; applying in memory''), loading ALL rows into JVM memory before paginating!", "B": "PostgreSQL paginates cleanly", "C": "Compile error", "D": "It runs faster"}'::jsonb, 'A', 'To paginate parent+children safely, first paginate parent IDs, then fetch children with WHERE id IN (:ids) (or use @BatchSize).', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000097'::uuid, 'Why is ''spring.jpa.open-in-view=true'' (Spring Boot''s default!) often disabled (''false'') in production APIs?', '{"A": "OSIV disables @Entity", "B": "OSIV blocks GET requests", "C": "OSIV keeps a DB connection/Hibernate Session open during controller JSON rendering, risking connection-pool exhaustion and hiding N+1 queries", "D": "OSIV deletes lazy fields"}'::jsonb, 'C', 'Setting open-in-view=false enforces fetching all DTO data cleanly within the service @Transactional boundary.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000098'::uuid, 'When a ''@Modifying'' bulk JPQL update runs in the middle of a transaction after entities were already loaded into the Persistence Context, what subtle bug can happen?', '{"A": "All rows are deleted", "B": "The transaction commits early", "C": "Hibernate throws an error", "D": "Bulk queries bypass the 1st-level cache, leaving stale entity state in memory unless ''@Modifying(clearAutomatically = true)'' is set"}'::jsonb, 'D', 'clearAutomatically=true (and flushAutomatically=true) keeps the Persistence Context consistent with bulk updates.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000099'::uuid, 'Why is ''@ManyToMany'' with ''List'' (bag) often worse in Hibernate than ''Set'' when removing an element?', '{"A": "Removing one element from a @ManyToMany List can cause Hibernate to DELETE ALL join rows for the parent and re-insert the remaining ones; Set deletes only the removed row", "B": "List cannot be lazy", "C": "List throws ClassCastException", "D": "Set doesn''t need a join table"}'::jsonb, 'A', 'Prefer Set (or an explicit link @Entity) for many-to-many associations.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000100'::uuid, 'When should you use Spring Data JPA DTO/Interface Projections in ''@Query'' instead of loading full ''@Entity'' objects?', '{"A": "When updating rows via dirty checking", "B": "For read-only endpoints/lists where only a few columns are needed—avoiding Persistence Context dirty-checking overhead and unnecessary column/LOB fetching", "C": "Projections cannot be used with JPQL", "D": "When you need CascadeType.ALL"}'::jsonb, 'B', 'Read-only projections reduce memory, network I/O, and Hibernate session tracking cost.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'spring-data-jpa-hibernate'), '70000000-0000-0000-0000-000000000097'::uuid, 'How does ''@Version'' optimistic locking in JPA prevent lost updates without holding database row locks during user think time?', '{"A": "It locks the table with SHARE LOCK", "B": "It stores versions in cookies", "C": "Hibernate adds ''WHERE id = ? AND version = ?'' and increments version on UPDATE; if 0 rows match, it throws OptimisticLockingFailureException", "D": "It disables transactions"}'::jsonb, 'C', 'Optimistic locking detects concurrent modifications at flush/commit time.', 'ADVANCED', TRUE);

-- Skill: unit-integration-testing
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000102'::uuid, 'Which annotation marks a test method in JUnit 5 (Jupiter)?', '{"A": "@Run", "B": "@Test", "C": "@Unit", "D": "@TestCase"}'::jsonb, 'B', 'org.junit.jupiter.api.Test marks a test method in JUnit 5.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000102'::uuid, 'What is the difference between ''@BeforeEach'' and ''@BeforeAll'' in JUnit 5?', '{"A": "@BeforeEach runs before every test method; @BeforeAll runs once before all tests in the class (typically static)", "B": "@BeforeAll runs after tests", "C": "They are identical", "D": "@BeforeEach runs only once"}'::jsonb, 'A', '@BeforeEach sets up fresh per-test state; @BeforeAll handles expensive one-time setup.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000102'::uuid, 'Which JUnit 5 assertion checks that a specific exception type is thrown by a lambda?', '{"A": "expectException(...)", "B": "tryAssert(...)", "C": "assertThrows(MyException.class, () -> service.call())", "D": "assertError(...)"}'::jsonb, 'C', 'assertThrows captures and returns the thrown exception for further assertions.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000103'::uuid, 'What is the purpose of Mockito in unit testing?', '{"A": "To create mock/fake implementations of dependencies (e.g., repositories) so the class under test is isolated", "B": "To deploy Docker containers", "C": "To compile SQL migrations", "D": "To start a real PostgreSQL server"}'::jsonb, 'A', 'Mocks isolate the unit under test from databases, networks, and external services.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000103'::uuid, 'How do ''@Mock'' and ''@InjectMocks'' work together in Mockito?', '{"A": "@Mock creates mock dependencies; @InjectMocks creates the real class under test and injects those mocks into it", "B": "@InjectMocks mocks static methods", "C": "Both create mocks", "D": "@Mock instantiates the database"}'::jsonb, 'A', 'Use @ExtendWith(MockitoExtension.class) to initialize @Mock and @InjectMocks cleanly.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000103'::uuid, 'What does ''when(repo.findById(id)).thenReturn(Optional.of(q))'' do?', '{"A": "Inserts q into PostgreSQL", "B": "Verifies the method was called", "C": "Deletes q", "D": "Stubs the mock repository to return Optional.of(q) when findById(id) is called"}'::jsonb, 'D', 'when(...).thenReturn(...) defines stubbed return values on a mock.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000104'::uuid, 'What does ''@SpringBootTest'' do compared to a plain JUnit + Mockito unit test?', '{"A": "It runs faster than unit tests", "B": "It loads the full Spring ApplicationContext to run integration tests across real wired beans", "C": "It disables Spring IoC", "D": "It tests only HTML"}'::jsonb, 'B', '@SpringBootTest boots the Spring context for end-to-end or multi-layer integration testing.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000104'::uuid, 'What is ''MockMvc'' used for in Spring Boot tests?', '{"A": "Mocking JDBC drivers", "B": "Generating React components", "C": "Testing Spring MVC controllers (HTTP routing, JSON serialization, status codes, validation) without starting a full HTTP port", "D": "Running Flyway"}'::jsonb, 'C', 'MockMvc simulates HTTP requests through DispatcherServlet and Spring Security filters.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000102'::uuid, 'What is ''@ParameterizedTest'' in JUnit 5 used for?', '{"A": "Testing Spring application.properties", "B": "Running one test method multiple times with different input arguments (e.g., via @ValueSource or @CsvSource)", "C": "Running tests in parallel threads", "D": "Mocking parameters"}'::jsonb, 'B', 'Parameterized tests eliminate duplicate test methods for edge-case input tables.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000102'::uuid, 'What does ''assertAll(...)'' in JUnit 5 achieve?', '{"A": "Stops at the first failing assertion", "B": "Asserts all mocks", "C": "Runs all test classes", "D": "Executes all grouped assertions and reports ALL failures together in one test run"}'::jsonb, 'D', 'Grouped assertions give complete failure diagnostics rather than hiding subsequent failures.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000103'::uuid, 'How does ''verify(repo, times(1)).save(any())'' differ from ''when(...).thenReturn(...)''?', '{"A": "verify() stubs return values", "B": "They are identical", "C": "when() sets up stubbed behavior BEFORE execution; verify() asserts AFTER execution that the interaction actually happened", "D": "verify() runs SQL"}'::jsonb, 'C', 'Stubbing configures inputs/outputs; verification checks behavioral side-effect calls.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000103'::uuid, 'What is an ''ArgumentCaptor'' in Mockito?', '{"A": "A Spring Security filter", "B": "A tool to capture the exact argument object passed into a mock method so you can assert its fields", "C": "A JUnit exception handler", "D": "A CLI flag parser"}'::jsonb, 'B', 'ArgumentCaptor lets you inspect the constructed MilestoneAttempt passed to attemptRepository.save().', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000103'::uuid, 'What is the difference between a Mock (''@Mock'') and a Spy (''@Spy'') in Mockito?', '{"A": "They are identical", "B": "A Spy cannot be verified", "C": "A Mock calls real methods", "D": "A Mock replaces all methods with no-op defaults unless stubbed; a Spy wraps a real object and calls real methods unless selectively stubbed"}'::jsonb, 'D', 'Use Spies sparingly when you need partial mocking of a real instance.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000104'::uuid, 'How do slice tests like ''@WebMvcTest'' or ''@DataJpaTest'' improve over ''@SpringBootTest''?', '{"A": "They test React too", "B": "They load ONLY the web or JPA slice of beans, making tests dramatically faster and more focused", "C": "They deploy to AWS", "D": "They skip JUnit"}'::jsonb, 'B', 'Slice tests avoid loading unnecessary layers when testing just controllers or repositories.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000104'::uuid, 'Why is H2 in-memory database sometimes misleading when testing PostgreSQL migrations/queries?', '{"A": "H2 doesn''t support SQL", "B": "H2 does not fully support PostgreSQL-specific types/syntax like JSONB, ::uuid casts, or Flyway PostgreSQL DDL", "C": "H2 rejects @Entity", "D": "H2 is slower than PostgreSQL"}'::jsonb, 'B', 'JSONB and PostgreSQL-specific SQL should be tested against real PostgreSQL (e.g., Testcontainers).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000104'::uuid, 'What does ''Testcontainers'' provide for Spring Boot integration tests?', '{"A": "Spins up a real, disposable Docker PostgreSQL container during tests so Flyway migrations and SQL run against genuine PostgreSQL", "B": "A React test runner", "C": "An in-memory Java HashMap", "D": "A Mockito plugin"}'::jsonb, 'A', 'Testcontainers eliminates H2 vs PostgreSQL dialect mismatches.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000104'::uuid, 'In ''@SpringBootTest'' tests, what does ''@Transactional'' on a test method do by default?', '{"A": "Disables Hibernate", "B": "Commits data permanently", "C": "Rolls back the transaction automatically after the test finishes, keeping the test DB clean", "D": "Runs 3 attempts"}'::jsonb, 'C', 'Auto-rollback prevents test pollution (note: be careful when testing real commit/lazy behavior across HTTP calls).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000102'::uuid, 'What is the ''Arrange-Act-Assert'' (AAA) pattern in unit testing?', '{"A": "A database normalization rule", "B": "Structuring each test into: set up inputs/mocks (Arrange), invoke the target method (Act), and verify outcomes (Assert)", "C": "Three JUnit annotations", "D": "A Git workflow"}'::jsonb, 'B', 'AAA keeps tests readable, focused, and easy to maintain.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000104'::uuid, 'In Spring Boot 3.4+, what annotation replaced the deprecated ''@MockBean'' for mocking beans inside a Spring test context?', '{"A": "@TestMock", "B": "@MockitoBean (from org.springframework.test.context.bean.override.mockito)", "C": "@FakeBean", "D": "@SpringMock"}'::jsonb, 'B', 'Spring Framework 6.2 / Boot 3.4+ introduced @MockitoBean and @MockitoSpyBean.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000104'::uuid, 'Why does using ''@MockitoBean'' with different configurations across many ''@SpringBootTest'' classes slow down a CI suite?', '{"A": "Spring deletes the JAR", "B": "Each distinct context configuration/mock set prevents Spring TestContext caching and forces booting a brand-new ApplicationContext", "C": "@MockitoBean runs sleep(5000)", "D": "JUnit runs single-threaded"}'::jsonb, 'B', 'Share a base integration test configuration so Spring reuses a single cached TestContext.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000103'::uuid, 'Why can ''doReturn(x).when(spy).method()'' be required instead of ''when(spy.method()).thenReturn(x)'' on a Mockito Spy?', '{"A": "doReturn() is faster", "B": "Spy ignores when()", "C": "Calling spy.method() inside when(...) actually invokes the real method first (which might throw or mutate state), whereas doReturn() stubs without invoking it", "D": "when() doesn''t compile on spies"}'::jsonb, 'C', 'Use doReturn/doThrow when stubbing spies or void methods.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000104'::uuid, 'When testing a ''@SpringBootTest(webEnvironment = RANDOM_PORT)'' endpoint that commits data on the server thread, why won''t ''@Transactional'' on the test method roll back what the HTTP server thread committed?', '{"A": "HTTP requests are read-only", "B": "RANDOM_PORT disables PostgreSQL", "C": "JUnit commits before HTTP", "D": "The server request runs in a separate HTTP thread with its own DB transaction, outside the test thread''s transaction"}'::jsonb, 'D', 'Clean up explicitly (or truncate/reset between tests) when using real HTTP calls with RANDOM_PORT.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000102'::uuid, 'What is a subtle risk of over-mocking (mocking value objects, DTOs, or every internal helper) in unit tests?', '{"A": "Tests become tightly coupled to internal implementation details and pass even when real integration contracts break", "B": "JUnit disallows >2 mocks", "C": "Mocks fail to compile", "D": "Code coverage becomes 0%"}'::jsonb, 'A', 'Mock external boundaries (DB, HTTP clients, clock), not simple domain data or the unit''s own internals.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'unit-integration-testing'), '70000000-0000-0000-0000-000000000104'::uuid, 'How does ''@DynamicPropertySource'' integrate Testcontainers PostgreSQL URLs into Spring Boot tests?', '{"A": "It edits application.properties on disk", "B": "It runs after Flyway", "C": "It registers the container''s dynamic JDBC URL, username, and password into Spring''s Environment before the ApplicationContext starts", "D": "It mocks DataSource"}'::jsonb, 'C', 'Or use ''@ServiceConnection'' (Spring Boot 3.1+) for zero-boilerplate container wiring.', 'ADVANCED', TRUE);

-- Skill: docker-cicd
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000105'::uuid, 'What is the difference between a Docker image and a Docker container?', '{"A": "A container is stored on Docker Hub; an image runs in RAM", "B": "Images cannot contain Java", "C": "They are identical", "D": "An image is a read-only template/blueprint; a container is a running (or stopped) writable instance of that image"}'::jsonb, 'D', 'Analogy: Image is to Class as Container is to Object.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000105'::uuid, 'In a Dockerfile, how do ''RUN'' and ''CMD'' differ?', '{"A": "CMD runs at build time", "B": "RUN runs when container starts", "C": "They are identical", "D": "RUN executes commands at image BUILD time (creating layers); CMD specifies the default command executed at container START time"}'::jsonb, 'D', 'Use RUN for installing packages/compiling, and CMD/ENTRYPOINT for launching the app.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
