INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000106'::uuid, 'What is Docker Compose (''compose.yaml'' / ''docker-compose.yml'') used for?', '{"A": "Defining and running multi-container applications (e.g., Spring Boot + PostgreSQL + React) with shared networks and volumes", "B": "Editing PNGs", "C": "Writing SQL queries", "D": "Replacing Java compilers"}'::jsonb, 'A', 'docker compose up starts all defined services together cleanly.', 'BEGINNER', TRUE);
