VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000106'::uuid, 'Why do we attach a Docker ''volume'' to a PostgreSQL container?', '{"A": "To make SQL faster", "B": "To compile Flyway", "C": "To persist database data outside the container lifecycle so data survives ''docker compose down'' or container recreation", "D": "To expose port 5432"}'::jsonb, 'C', 'Without a volume, container removal wipes the database''s writable layer.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000107'::uuid, 'What does CI/CD stand for?', '{"A": "Code Inspection / Code Deletion", "B": "Continuous Integration / Continuous Delivery (or Deployment)", "C": "Container Image / Container Deployment", "D": "Central Interface / Central Database"}'::jsonb, 'B', 'CI automates building and testing on every commit; CD automates releasing/deploying.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
