INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000105'::uuid, 'What is the purpose of a ''.dockerignore'' file?', '{"A": "To ignore Dockerfile errors", "B": "To exclude unnecessary files (target/, node_modules/, .git/, .env) from the Docker build context", "C": "To hide Docker from Git", "D": "To stop containers"}'::jsonb, 'B', 'Excluding large/sensitive directories speeds up builds and prevents leaking secrets into images.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000105'::uuid, 'Why is a multi-stage Dockerfile recommended for Java / Spring Boot applications?', '{"A": "Multi-stage disables layers", "B": "It runs two containers at once", "C": "Single-stage cannot run Maven", "D": "Stage 1 builds the JAR using a full JDK/Maven image; Stage 2 copies only the JAR into a slim JRE image, cutting final image size dramatically and reducing attack surface"}'::jsonb, 'D', 'Removing Maven, source code, and JDK compilers from the runtime image shrinks size from ~700MB to ~200MB.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000105'::uuid, 'Why should you copy ''pom.xml'' and download dependencies BEFORE copying ''src/'' in a Dockerfile?', '{"A": "To skip tests", "B": "src/ deletes pom.xml", "C": "Docker requires pom.xml first", "D": "To leverage Docker layer caching so code edits in src/ don''t re-download all Maven dependencies on every build"}'::jsonb, 'D', 'Ordering least-frequently changed files first maximizes build cache hits.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000105'::uuid, 'How does ''EXPOSE 8080'' in a Dockerfile differ from ''docker run -p 8080:8080''?', '{"A": "EXPOSE is documentation metadata only; ''-p'' actually publishes and maps the container port to the host", "B": "EXPOSE opens the firewall automatically", "C": "They are identical", "D": "-p is only for UDP"}'::jsonb, 'A', 'Ports are not reachable from the host unless explicitly published with -p / ports:.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000106'::uuid, 'In Docker Compose, why is ''depends_on: postgres'' alone NOT enough to guarantee PostgreSQL is ready for Spring Boot?', '{"A": "depends_on by default waits only for container start, not for PostgreSQL to finish initializing and accepting TCP connections; use ''condition: service_healthy'' with a healthcheck (pg_isready)", "B": "Spring Boot starts before Docker", "C": "depends_on deletes Postgres", "D": "Compose has no networks"}'::jsonb, 'A', 'Pair healthcheck (pg_isready) with condition: service_healthy to avoid startup connection-refused errors.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000106'::uuid, 'Inside a Docker Compose network, what hostname should Spring Boot use in ''DB_URL'' to connect to the ''postgres'' service?', '{"A": "127.0.0.1", "B": "0.0.0.0", "C": "The Compose service name (e.g., jdbc:postgresql://postgres:5432/ai_upskilling)", "D": "localhost"}'::jsonb, 'C', 'Inside a container, ''localhost'' refers to the backend container itself, not the sibling postgres container.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000107'::uuid, 'What typical stages belong in a backend CI pipeline before merging a PR?', '{"A": "Deploy to Production -> Run Tests", "B": "Delete migrations -> Push", "C": "Checkout -> Build/Compile -> Run Unit & Integration Tests -> Static Analysis/Lint -> Build Docker Image", "D": "Format disk -> Reboot"}'::jsonb, 'C', 'Failing fast on compile/test/lint prevents broken code from reaching main.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000107'::uuid, 'How should database passwords, JWT secrets, and API keys be provided in CI/CD pipelines?', '{"A": "Printed in logs", "B": "Stored in encrypted CI Secrets / Secret Manager and injected at runtime as environment variables", "C": "Committed in application.properties", "D": "Hardcoded in Dockerfile ENV"}'::jsonb, 'B', 'Never bake secrets into Git commits or Dockerfile layers.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000105'::uuid, 'Why is running a container as a non-root user (''USER appuser'') a security best practice?', '{"A": "Root cannot run Java", "B": "Non-root uses less RAM", "C": "Docker requires it to expose port 8080", "D": "It limits blast radius if the application is compromised inside the container"}'::jsonb, 'D', 'Least-privilege container execution prevents root-level host/volume abuse.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000106'::uuid, 'What is the difference between ''docker compose down'' and ''docker compose down -v''?', '{"A": "down stops/removes containers and networks while preserving named volumes; ''-v'' ALSO deletes named volumes (wiping DB data!)", "B": "They are identical", "C": "-v backs up volumes", "D": "down deletes images"}'::jsonb, 'A', 'Be careful with ''-v'' if you want to keep PostgreSQL data across restarts.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000107'::uuid, 'Why is tagging Docker images with '':latest'' alone in production CD pipelines discouraged?', '{"A": "Kubernetes cannot pull '':latest''", "B": "Docker rejects '':latest''", "C": "'':latest'' is mutable and non-reproducible—you cannot tell which exact Git commit is running or roll back cleanly; tag with the Git SHA or semantic version", "D": "'':latest'' is larger"}'::jsonb, 'C', 'Immutable commit-SHA tags guarantee traceable deployments and reliable rollbacks.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000105'::uuid, 'Why is exec-form ''ENTRYPOINT ["java", "-jar", "app.jar"]'' strongly preferred over shell-form ''ENTRYPOINT java -jar app.jar''?', '{"A": "Exec-form runs Java directly as PID 1 so SIGTERM signals reach the JVM for graceful shutdown; shell-form wraps it in ''/bin/sh -c'' which may swallow SIGTERM", "B": "Exec-form disables stdout", "C": "Shell-form runs twice", "D": "Shell-form cannot pass -jar"}'::jsonb, 'A', 'PID 1 signal forwarding is essential for graceful shutdown in Kubernetes and ECS.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000105'::uuid, 'Why does Spring Boot support ''layered JARs'' (jarmode=tools / layertools) when building Docker images?', '{"A": "Extracting dependencies, spring-boot-loader, snapshot-dependencies, and application classes into separate Docker layers means rebuilding app code only invalidates the tiny top layer", "B": "It replaces the JVM", "C": "It encrypts .class files", "D": "It merges all JARs into SQL"}'::jsonb, 'A', 'Layered JARs drastically reduce CI push/pull bandwidth on frequent code changes.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000107'::uuid, 'In a zero-downtime blue-green or rolling deployment with Flyway, why must new database migrations be backward-compatible with the currently running old app version?', '{"A": "During rollout, both old and new app instances temporarily share the same database schema; dropping/renaming a column immediately breaks old instances", "B": "Old containers auto-recompile", "C": "Flyway runs after traffic shifts", "D": "PostgreSQL locks all reads during rollout"}'::jsonb, 'A', 'Use the expand-and-contract pattern: add new columns/tables first, deploy new code, then remove legacy columns in a later release.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000106'::uuid, 'How does Docker''s cgroup memory limit interact with the JVM (Java 17/21) when running in a container?', '{"A": "Docker disables GC", "B": "Modern JVMs are container-aware (UseContainerSupport) and size heap relative to the container''s cgroup memory limit rather than host RAM (configurable via -XX:MaxRAMPercentage)", "C": "JVM ignores container limits completely", "D": "JVM always allocates 64MB"}'::jsonb, 'B', 'Setting -XX:MaxRAMPercentage=75.0 leaves headroom for metaspace, threads, and native memory to avoid OOMKills.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000107'::uuid, 'What is ''BuildKit cache mounting'' (''RUN --mount=type=cache,target=/root/.m2 mvn package'') in modern Dockerfiles?', '{"A": "Persists the Maven/Gradle cache across builds on the builder host without baking the cache directory into the final image layer", "B": "Disables pom.xml", "C": "Caches HTTP responses in production", "D": "Uploads .m2 to Docker Hub"}'::jsonb, 'A', 'Cache mounts give fast incremental builds with zero image bloat.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'docker-cicd'), '70000000-0000-0000-0000-000000000107'::uuid, 'Why should CI pipelines run Flyway migrations (or schema validation tests) against a real PostgreSQL service/Testcontainer before deploying?', '{"A": "To catch SQL syntax errors, duplicate migration versions (like V13!), or checksum mismatches before they crash production startup", "B": "To generate random UUIDs", "C": "To bypass Git", "D": "To skip unit tests"}'::jsonb, 'A', 'Testing migrations in CI prevents broken deploys and startup outages.', 'ADVANCED', TRUE);
